/* Gradnetz- und Atlaswerkstatt. Eigene SVG-Lernmodelle, keine Laufzeitdienste. */
'use strict';
(function(){
const ROOT=typeof MAIN!=='undefined'?MAIN:document.getElementById('main');
if(!ROOT)return;
const D=Math.PI/180,BLUE='#1766a1',PINK='#9c3475',GREEN='#086f62';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.abs(n).toLocaleString('de-DE',{maximumFractionDigits:1});
const latText=n=>`${fmt(n)}° ${n===0?'(Äquator)':n>0?'N':'S'}`;
const lonText=n=>`${fmt(n)}° ${n===0?'(Nullmeridian)':Math.abs(n)===180?'(180°-Meridian)':n>0?'O':'W'}`;
const coord=(lat,lon)=>`${latText(lat)} · ${lonText(lon)}`;
const round=n=>Math.round(n*10)/10;
const cityData=window.AW_DATA.cities;
const maps=window.AW_DATA.maps;
function quarter(lat,lon){
 if(Math.abs(lat)===90)return {code:'pole',name:lat>0?'Nordpol':'Südpol',detail:'Am Pol treffen sich alle Meridiane. Eine eindeutige östliche oder westliche Länge gibt es dort nicht.'};
 if(lat===0||lon===0||Math.abs(lon)===180)return {code:'edge',name:'Auf einer Grenze',detail:'Äquator, Nullmeridian und 180°-Meridian sind Grenzen. Ordne den Punkt keinem einzelnen Erdviertel zu.'};
 const code=(lat>0?'N':'S')+(lon>0?'O':'W');
 return {code,name:({NO:'Nordostviertel',NW:'Nordwestviertel',SO:'Südostviertel',SW:'Südwestviertel'})[code],detail:`${lat>0?'Nördlich':'Südlich'} des Äquators und ${lon>0?'östlich':'westlich'} des Nullmeridians.`};
}
function number(raw,max){
 const s=String(raw).trim().replace(',','.');
 if(!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))return null;
 const n=Number(s);return Number.isFinite(n)&&n>=0&&n<=max?n:null;
}
function checkMissing(raw,dir,target,isLat,otherTarget=null){
 const n=number(raw,isLat?90:180);
 if(n===null)return {ok:false,code:'range',text:`Trage eine positive Zahl von 0 bis ${isLat?90:180} ein. N/S bzw. O/W wählst du im Richtungsfeld. Ein Dezimalkomma ist erlaubt.`};
 if(!(isLat?['N','S']:['O','W']).includes(dir))return {ok:false,code:'direction',text:'Wähle die passende Himmelsrichtung aus.'};
 const sign=(dir==='S'||dir==='W')?-1:1,val=n*sign;
 if(otherTarget!==null&&Math.abs(n-Math.abs(otherTarget))<=.16&&Math.abs(n-Math.abs(target))>.16)return {ok:false,code:'swapped',text:`Du hast den bereits gegebenen ${isLat?'Längengrad':'Breitengrad'} eingetragen. Gesucht ist die andere Koordinate. Breite: N/S. Länge: O/W.`};
 if(n!==0&&sign!==Math.sign(target))return {ok:false,code:'direction',text:`Prüfe ${isLat?'Nord und Süd':'Ost und West'}. Die Zahl allein genügt noch nicht; die Richtung muss zur Lage passen.`};
 const ok=Math.abs(val-target)<=.16;
 return {ok,code:ok?'correct':'reading',text:ok?'Gut abgelesen! Der Wert passt zur gerundeten Ortslage.':'Die Richtung passt. Lies jetzt die Zahl am Rand der passenden Gradlinie ab. Prüfe die Schrittweite und schätze zwischen zwei Linien.'};
}
const persisted=(()=>{try{return JSON.parse(localStorage.getItem('geo-atlaswerkstatt-v1')||'{}')}catch{return {}}})();
const s={view:'notes',lat:50,lon:14,camLon:0,camLat:18,layer:'both',spin:false,city:0,mode:'coords',step:0,playing:false,answer:'',direction:'O',feedback:null,quarterIndex:0,quarterFeedback:null,viewAnswers:{},viewFeedback:'',gaps:{},gapFeedback:null,gapSolution:false,gapSeenSolution:false,done:new Set(Array.isArray(persisted.done)?persisted.done.filter(x=>typeof x==='string'&&x.length<60):[])};
let raf=0,timer=0,last=0;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function mark(key){s.done.add(key);try{localStorage.setItem('geo-atlaswerkstatt-v1',JSON.stringify({done:[...s.done],stats:s.stats}))}catch{}}
function stop(){cancelAnimationFrame(raf);clearTimeout(timer);raf=0;timer=0;s.spin=false;s.playing=false;last=0;}
function button(label,act,extra=''){return `<button type="button" data-aw="${act}" ${extra}>${label}</button>`;}
function feedback(f){return f?`<div class="aw-feedback" role="status" data-good="${f.ok}">${E(f.text)}</div>`:'';}
function svg(title,body,vb='0 0 640 430',cls='aw-svg'){return `<svg class="${cls}" viewBox="${vb}" role="img" aria-label="${E(title)}" xmlns="http://www.w3.org/2000/svg"><title>${E(title)}</title>${body}</svg>`;}
function project(lat,lon,camLat=0,camLon=0,r=164,cx=320,cy=212){
 const a=lat*D,b=(lon-camLon)*D,p=camLat*D;
 return [cx+r*Math.cos(a)*Math.sin(b),cy-r*(Math.cos(p)*Math.sin(a)-Math.sin(p)*Math.cos(a)*Math.cos(b)),Math.sin(p)*Math.sin(a)+Math.cos(p)*Math.cos(a)*Math.cos(b)];
}
function curve(points,col,width=1.2,back=false){
 let front='',rear='',prev=null;
 for(const p of points){const vis=p[2]>=-1e-8;const q=`${p[0].toFixed(2)},${p[1].toFixed(2)}`;
  if(vis)front+=(prev===true?'L':'M')+q;else rear+=(prev===false?'L':'M')+q;prev=vis;}
 return `${back?`<path d="${rear}" fill="none" stroke="${col}" opacity=".22" stroke-dasharray="4 5" stroke-width="${width}"/>`:''}<path d="${front}" fill="none" stroke="${col}" stroke-width="${width}"/>`;
}
function globeGraphic(camLat=s.camLat,camLon=s.camLon,layer=s.layer,selected=true){
 const pp=(la,lo)=>project(la,lo,camLat,camLon),a=[];
 a.push('<circle cx="320" cy="212" r="164" fill="#e3f1f8" stroke="#567f95" stroke-width="2"/>');
 if(layer!=='lon')for(let lat=-60;lat<=60;lat+=30)a.push(curve(Array.from({length:181},(_,i)=>pp(lat,-180+i*2)),BLUE,lat===0?3:1.3,true));
 if(layer!=='lat')for(let lon=-180;lon<180;lon+=30)a.push(curve(Array.from({length:91},(_,i)=>pp(-90+i*2,lon)),PINK,lon===0?3:1.2,true));
 if(selected){
  if(layer!=='lon')a.push(curve(Array.from({length:181},(_,i)=>pp(s.lat,-180+i*2)),BLUE,4));
  if(layer!=='lat')a.push(curve(Array.from({length:91},(_,i)=>pp(-90+i*2,s.lon)),PINK,4));
  const p=pp(s.lat,s.lon);if(p[2]>=0)a.push(`<circle cx="${p[0]}" cy="${p[1]}" r="7" fill="#f6ce55" stroke="#17394e" stroke-width="2"/>`);
 }
 const pole=pp(90,0),south=pp(-90,0);
 for(const [p,t] of [[pole,'Nordpol · 90° N'],[south,'Südpol · 90° S']])if(p[2]>-.02)a.push(`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#17394e"/><text x="${p[0]+10}" y="${p[1]-9}" font-size="14" fill="#17394e">${t}</text>`);
 a.push('<text x="320" y="413" text-anchor="middle" font-size="14" fill="#405e70">Durchsichtige Modellkugel · Rückseite gestrichelt</text>');
 return svg(`Gradnetz, Blick aus ${Math.round(camLat)}° Breite und ${Math.round(camLon)}° Länge. Breitenkreise blau, Meridiane violett.`,a.join(''));
}
function angleGraphic(){
 const lat=s.lat,theta=lat*D,cx=155,cy=125,r=83,x=cx+r*Math.cos(theta),y=cy-r*Math.sin(theta);
 const small=36,ax=cx+small*Math.cos(theta),ay=cy-small*Math.sin(theta),sweep=lat>=0?0:1;
 return svg(`Breitenwinkel ${latText(lat)} vom Äquator aus gemessen`,`<circle cx="155" cy="125" r="83" fill="#eaf4fa" stroke="#728c9d"/><path d="M55 125H255" stroke="${BLUE}" stroke-width="2"/><path d="M155 25V225" stroke="#728c9d" stroke-dasharray="4 4"/><path d="M155 125L${x} ${y}" stroke="${PINK}" stroke-width="3"/><path d="M191 125A36 36 0 0 ${sweep} ${ax} ${ay}" fill="none" stroke="#9b6100" stroke-width="3"/><circle cx="155" cy="125" r="3" fill="#17394e"/><circle cx="${x}" cy="${y}" r="4" fill="${PINK}"/><text x="262" y="130" font-size="13" fill="${BLUE}">Äquator 0°</text><text x="165" y="21" font-size="13" fill="#17394e">Nordpol</text><text x="165" y="244" font-size="13" fill="#17394e">Südpol</text><text x="15" y="267" font-size="14" fill="#17394e">Erdmittelpunkt → Winkel: ${latText(lat)}</text>`,'0 0 350 282');
}
let awMapUid=0;
function flatMap(key='world',opts={}){
 const m=maps[key],bounds=m.bounds,[west,east,south,north]=bounds,x0=63,y0=42,w=650,h=330,id='awMapClip'+(++awMapUid);
 const X=n=>x0+(n-west)/(east-west)*w,Y=n=>y0+(north-n)/(north-south)*h;
 let a=`<defs><clipPath id="${id}"><rect x="${x0}" y="${y0}" width="${w}" height="${h}"/></clipPath></defs><rect x="${x0}" y="${y0}" width="${w}" height="${h}" fill="#e1f0f8"/>`;
 if(opts.quarters&&key==='world')for(const [lo,la,col] of [[-180,90,'#d5e9ff'],[0,90,'#e0f0d3'],[-180,0,'#f8e4d5'],[0,0,'#eee1f6']])a+=`<rect x="${X(lo)}" y="${Y(la)}" width="${w/2}" height="${h/2}" fill="${col}"/>`;
 if(typeof WORLD_LAND!=='undefined')a+=`<g clip-path="url(#${id})" fill="#c1d5bc" stroke="#718d78" stroke-width=".6">${WORLD_LAND.map(poly=>`<path d="${poly.map(([lo,la],i)=>(i?'L':'M')+X(lo).toFixed(1)+','+Y(la).toFixed(1)).join('')}Z"/>`).join('')}</g>`;
 for(let lo=Math.ceil(west/m.step)*m.step;lo<=east;lo+=m.step)a+=`<path d="M${X(lo)} ${y0}V${y0+h}" stroke="${PINK}" opacity="${lo===0?1:.35}" stroke-width="${lo===0?2.5:1}"/><text x="${X(lo)}" y="${y0-12}" text-anchor="middle" fill="${PINK}" font-size="13">${lo===0?'0°':fmt(lo)+'° '+(lo<0?'W':'O')}</text>`;
 for(let la=Math.ceil(south/m.step)*m.step;la<=north;la+=m.step)a+=`<path d="M${x0} ${Y(la)}H${x0+w}" stroke="${BLUE}" opacity="${la===0?1:.35}" stroke-width="${la===0?2.5:1}"/><text x="${x0-8}" y="${Y(la)+4}" text-anchor="end" fill="${BLUE}" font-size="13">${la===0?'0°':fmt(la)+'° '+(la<0?'S':'N')}</text>`;
 if(opts.quarters&&key==='world')for(const [lo,la,t] of [[-90,65,'Nordwestviertel'],[90,65,'Nordostviertel'],[-90,-65,'Südwestviertel'],[90,-65,'Südostviertel']])a+=`<text x="${X(lo)}" y="${Y(la)}" text-anchor="middle" font-weight="700" font-size="17" fill="#17394e" stroke="#fff" stroke-width="4" paint-order="stroke">${t}</text>`;
 const city=opts.city,inside=p=>p.lon>=west&&p.lon<=east&&p.lat>=south&&p.lat<=north;
 if(city&&inside(city)){
  if(opts.lat)a+=`<path d="M${x0} ${Y(city.lat)}H${x0+w}" stroke="${BLUE}" stroke-width="4"/><text x="${x0+10}" y="${Y(city.lat)-9}" fill="${BLUE}" stroke="#fff" stroke-width="4" paint-order="stroke" font-size="16" font-weight="700">Breite: ${latText(city.lat)}</text>`;
  if(opts.lon)a+=`<path d="M${X(city.lon)} ${y0}V${y0+h}" stroke="${PINK}" stroke-width="4"/><text x="${Math.min(x0+w-170,Math.max(x0+10,X(city.lon)+10))}" y="${y0+22}" fill="${PINK}" stroke="#fff" stroke-width="4" paint-order="stroke" font-size="16" font-weight="700">Länge: ${lonText(city.lon)}</text>`;
  if(opts.point)a+=`<circle cx="${X(city.lon)}" cy="${Y(city.lat)}" r="7" fill="#f4c943" stroke="#17394e" stroke-width="2"/>`;
 }
 const labels=[];
 if(opts.names)for(const p of cityData.filter(p=>inside(p)&&(!opts.onlyCity||p.id===opts.onlyCity))){
  const px=X(p.lon),py=Y(p.lat),font=p.name.length>12?13:15,tw=p.name.length*font*.55;
  const candidates=[];for(const dy of [20,-12,36,-28,52,-44,68,-60])for(const side of [1,-1]){const x=Math.max(x0+4,Math.min(x0+w-tw-4,px+(side===1?9:-tw-9))),y=Math.max(y0+16,Math.min(y0+h-5,py+dy));const r={x,y,w:tw,h:18};let score=0;for(const q of labels){const ix=Math.max(0,Math.min(r.x+r.w,q.x+q.w)-Math.max(r.x,q.x)),iy=Math.max(0,Math.min(r.y+4,q.y+4)-Math.max(r.y-14,q.y-14));score+=ix*iy;}candidates.push({...r,score});}
  const place=candidates.find(r=>r.score===0)||candidates.sort((a,b)=>a.score-b.score)[0];labels.push(place);
  a+=`<path d="M${px} ${py}L${place.x} ${place.y-5}" stroke="#718693" stroke-width=".8"/><circle cx="${px}" cy="${py}" r="4" fill="#17394e"/><text x="${place.x}" y="${place.y}" fill="#17394e" stroke="#fff" stroke-width="4" paint-order="stroke" font-size="${font}">${E(p.name)}</text>`;
 }
 if(opts.fields){for(let i=0;i<=4;i++){const x=x0+i*w/4,y=y0+i*h/4;a+=`<path d="M${x} ${y0}V${y0+h}M${x0} ${y}H${x0+w}" stroke="#17394e" stroke-width="1.5" stroke-dasharray="6 5"/>`;if(i<4)a+=`<text x="${x+w/8}" y="397" text-anchor="middle" font-size="17" font-weight="700" fill="#17394e">${String.fromCharCode(65+i)}</text><text x="733" y="${y+h/8+5}" font-size="17" font-weight="700" fill="#17394e">${i+1}</text>`;}
  if(opts.fieldHighlight){const col=opts.fieldHighlight.charCodeAt(0)-65,row=Number(opts.fieldHighlight[1])-1;a+=`<rect x="${x0+col*w/4}" y="${y0+row*h/4}" width="${w/4}" height="${h/4}" fill="#e6a129" fill-opacity=".2" stroke="#925b00" stroke-width="3"/>`;}}
 if(opts.marker&&inside(opts.marker)){const p=opts.marker;a+=`<g stroke="#17394e" stroke-width="2"><path d="M${X(p.lon)-9} ${Y(p.lat)}h18M${X(p.lon)} ${Y(p.lat)-9}v18"/><circle cx="${X(p.lon)}" cy="${Y(p.lat)}" r="6" fill="#ffdf68"/></g>`;}
 a+=`<rect x="${x0}" y="${y0}" width="${w}" height="${h}" fill="none" stroke="#4e758a"/><text x="${x0}" y="425" fill="#405e70" font-size="12">${E(m.name)} · vereinfachtes Modell · Küsten: Natural Earth (Public Domain)</text>`;
 let art=svg(`${m.name} mit Gradnetz; Breite links, Länge oben.${opts.pick?' Markiere den Punkt durch Antippen; Richtungstasten stehen unter der Karte.':''}`,a,'0 0 760 440','aw-svg');
 if(opts.pick)art=art.replace('<svg ',`<svg data-aw-pick="${opts.pick}" data-aw-map-key="${key}" `);
 return `<div class="aw-map-scroll" tabindex="0" role="region" aria-label="Karte, bei schmaler Ansicht seitlich verschiebbar" style="--aw-map-zoom:${s.mapZoom||1}">${art}</div><p class="aw-map-hint aw-muted">Karte seitlich verschieben oder mit + / − vergrößern. Auf Touchgeräten ist auch die Browser-Vergrößerung möglich.</p>`;
}

function globeView(){
 return `<div class="aw-grid"><div><section class="aw-card"><h2>Eine Erde, zwei Arten von Linien</h2><div class="aw-controls">${[['both','Beide Linien'],['lat','Nur Breitenkreise'],['lon','Nur Meridiane']].map(([k,t])=>button(t,'layer:'+k,`aria-pressed="${s.layer===k}"`)).join('')}</div><div class="aw-controls">${button("− Globus","globeZoom:-1","aria-label=\"Globus verkleinern\"")}<output>${Math.round(s.globeZoom*100)} %</output>${button("+ Globus","globeZoom:1","aria-label=\"Globus vergrößern\"")}</div><div id="awGlobe" class="aw-globe" style="--aw-globe-zoom:${s.globeZoom}">${globeGraphic()}</div><div class="aw-controls">${button('Blick vom Äquator','camera:equator')}${button('Blick auf den Nordpol','camera:north')}${button('Blick auf den Südpol','camera:south')}</div><div class="aw-controls" style="margin-top:10px">${button(reduced()?'20° weiterdrehen':'Drehung starten','spin','id="awSpin" aria-pressed="false"')}${button('Gewählten Punkt nach vorn holen','focus')}</div><label for="awCamera">Erde nach Osten oder Westen drehen</label><input id="awCamera" data-aw-input="camLon" type="range" min="-180" max="180" step="1" value="${s.camLon}"><label for="awTilt">Blick zwischen Südpol und Nordpol kippen</label><input id="awTilt" data-aw-input="camLat" type="range" min="-90" max="90" step="1" value="${s.camLat}"><p class="aw-muted">Du steuerst die Ansicht mit Reglern oder Tasten. Beim Verlassen hält die Drehung an.</p></section><section class="aw-card"><h3>Warum heißt es Breitengrad?</h3><p>Auf der Modellkugel ist die Breite ein <b>Winkel vom Äquator aus</b>. Ein Grad ist hier ein Winkelmaß, keine Temperatur und keine feste Weglänge.</p><div id="awAngle">${angleGraphic()}</div></section></div><div><section class="aw-card"><h2>Bewege den gelben Punkt</h2><p>Ändere erst die Breite, dann die Länge. Die dickeren Linien schneiden sich am gewählten Punkt.</p><label class="aw-lat" for="awLatitude">Breite: <output id="awLatOut">${latText(s.lat)}</output></label><input id="awLatitude" data-aw-input="lat" type="range" min="-90" max="90" value="${s.lat}"><label class="aw-lon" for="awLongitude">Länge: <output id="awLonOut">${lonText(s.lon)}</output></label><input id="awLongitude" data-aw-input="lon" type="range" min="-180" max="180" value="${s.lon}"><div id="awPoint" class="aw-stat">${pointSummary()}</div><div class="aw-callout"><b>Breitenkreise</b> verlaufen parallel zum Äquator. Die Breite sagt: wie weit <b>nördlich oder südlich</b>?<br><b>Meridiane</b> führen von Pol zu Pol. Die Länge sagt: wie weit <b>östlich oder westlich</b>?</div><p><b>Breite:</b> 0° am Äquator, bis 90° N oder 90° S.<br><b>Länge:</b> 0° am Nullmeridian durch Greenwich, bis 180° O oder 180° W.</p><details><summary>Längenkreis oder Meridian?</summary><p>Ein Meridian ist ein Halbkreis von Pol zu Pol. Mit dem gegenüberliegenden Meridian bildet er einen ganzen Längenkreis. Ein Breitenkreis ist ein ganzer Kreis; an den Polen schrumpft er zum Punkt.</p></details><details><summary>Wo liegt die Datumsgrenze?</summary><p>Der 180°-Meridian liegt dem Nullmeridian gegenüber. Die internationale Datumsgrenze verläuft ungefähr dort, weicht aber an einigen Stellen ab. Sie ist keine gerade Linie entlang des gesamten Meridians.</p></details></section></div></div>`;
}
function pointSummary(){const q=quarter(s.lat,s.lon),p=project(s.lat,s.lon,s.camLat,s.camLon);return `${coord(s.lat,s.lon)}<br>${q.name}<div class="aw-small">${p[2]<0?'Der Punkt liegt gerade auf der Rückseite. Hole ihn nach vorn.':q.detail}</div>`;}
const quarterTasks=[[50,14],[-30,80],[40,-120],[-20,-60],[0,45],[35,0],[-30,180],[90,80]];
function hemisphereModels(){
 return `<details><summary>Nord-, Süd-, Ost- und Westhalbkugel im Modell vergleichen</summary><p>Jeder Blick zeigt genau eine Halbkugel. Die Gegenseite liegt dahinter. Wähle im Gradnetzbereich dieselbe Ansicht, um die Erde zu drehen.</p><div class="aw-grid2">${[[90,0,'Nordhalbkugel','Grenze: Äquator','#e0edfc'],[-90,0,'Südhalbkugel','Grenze: Äquator','#e2f3e9'],[0,90,'Osthalbkugel','Grenzen: 0° und 180°','#f4e6ee'],[0,-90,'Westhalbkugel','Grenzen: 0° und 180°','#f8efd9']].map(([la,lo,title,desc,col])=>`<section class="aw-card aw-viewcard"><h3>${title}</h3>${globeGraphic(la,lo,'both',false).replace('fill="#e3f1f8"',`fill="${col}"`)}<p>${desc}</p></section>`).join('')}</div></details>`;
}
function quartersView(){
 const t=quarterTasks[s.quarterIndex],q=quarter(t[0],t[1]);
 return `${hemisphereModels()}<div class="aw-grid"><section class="aw-card"><h2>Aus zwei Halbkugeln wird ein Erdviertel</h2><p>Der <b>Äquator</b> trennt Nord und Süd. <b>Nullmeridian und 180°-Meridian</b> grenzen Ost- und Westhalbkugel voneinander ab.</p>${flatMap('world',{quarters:true})}<div class="aw-callout">Beispiel: <b>50° N und 14° O → Nordostviertel</b>. Auf der Weltkarte liegt es oben rechts. Ein Erdviertel ist kein Kontinent.</div><p class="aw-muted">Die flache Weltkarte verzerrt Flächen. Die vier Erdviertel sind auf der Kugel gleich große Teile.</p></section><section class="aw-card"><span class="aw-kicker">Aufgabe ${s.quarterIndex+1} / ${quarterTasks.length}</span><h2>In welchem Erdviertel?</h2><div class="aw-stat">${coord(...t)}</div><div class="aw-quarter">${[['NW','Nordwestviertel','N + W'],['NO','Nordostviertel','N + O'],['SW','Südwestviertel','S + W'],['SO','Südostviertel','S + O'],['edge','Auf einer Grenze','0° oder 180°'],['pole','Am Pol','90° N oder 90° S']].map(([k,title,sub])=>button(`${title}<span>${sub}</span>`,'quarter:'+k)).join('')}</div>${feedback(s.quarterFeedback)}<div class="aw-controls" style="margin-top:15px">${button('Nächste Aufgabe →','quarterNext')}</div><details data-aw-quarter-help><summary>Gustavs Hilfe</summary><p>Lies N oder S für die erste Hälfte. Lies O oder W für die zweite Hälfte. Steht dort 0°, 180° oder ein Pol, prüfe zuerst den Sonderfall.</p></details><p class="aw-muted">Die Grenzen werden nicht willkürlich einem Viertel zugeschlagen.</p></section></div>`;
}
function viewModel(kind){
 if(kind==='parallel-side')return globeGraphic(0,0,'lat',false);
 if(kind==='parallel-pole')return globeGraphic(90,0,'lat',false);
 if(kind==='meridian-side')return globeGraphic(0,0,'lon',false);
 return globeGraphic(90,0,'lon',false);
}
const viewCases=[['parallel-side','Nur Breitenkreise · Blick vom Äquator','waagerecht'],['parallel-pole','Nur Breitenkreise · Blick auf den Nordpol','ringe'],['meridian-side','Nur Meridiane · Blick vom Äquator','boegen'],['meridian-pole','Nur Meridiane · Blick auf den Nordpol','strahlen']];
function viewsView(){return `<section class="aw-card"><h2>Was verändert die Blickrichtung?</h2><p>Die Linien auf der Erde bleiben gleich. Von der Seite und vom Pol sehen sie verschieden aus. Betrachte die vier Modelle wie die vier Felder auf deinem Arbeitsblatt.</p><details data-aw-view-help><summary>Erklärung als Hilfe anzeigen</summary><div class="aw-callout"><b>Vom Pol:</b> Breitenkreise erscheinen als Ringe. Meridiane laufen wie Speichen zum Pol.<br><b>Vom Äquator:</b> Breitenkreise erscheinen waagerecht. Meridiane sind gebogene Linien; der mittlere erscheint gerade.</div></details></section><div class="aw-grid2">${viewCases.map(([id,title])=>`<section class="aw-card aw-viewcard"><h3>${title}</h3>${viewModel(id)}<label for="awView-${id}">Welche Form erkennst du?</label><select id="awView-${id}" data-aw-view="${id}"><option value="">Bitte auswählen</option>${[['waagerecht','Waagerechte Linien'],['ringe','Ringe um den Pol'],['boegen','Bögen von Pol zu Pol'],['strahlen','Speichen / Strahlen zum Pol']].map(([v,t])=>`<option value="${v}" ${s.viewAnswers[id]===v?'selected':''}>${t}</option>`).join('')}</select></section>`).join('')}</div><section class="aw-card">${button('Meine vier Zuordnungen prüfen','checkViews','class="aw-primary"')}<div id="awViewsFeedback" role="status">${s.viewFeedback}</div><p>Vom Südpol sehen Breitenkreise ebenfalls wie Ringe und Meridiane wie Speichen aus. Probiere den Blickwechsel im ersten Bereich aus.</p></section>`;}
const normalize=t=>String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
function task(){const p=cityData[s.city];return s.mode==='coords'?`Gesucht: Welche Stadt liegt ungefähr bei <b>${coord(p.lat,p.lon)}</b>?`:s.mode==='nameLat'?`Gegeben: <b>${p.name}, ${p.country}</b>, und <b>${latText(p.lat)}</b>. Gesucht: die <b>Länge</b>.`:`Gegeben: <b>${p.name}, ${p.country}</b>, und <b>${lonText(p.lon)}</b>. Gesucht: die <b>Breite</b>.`;}
function fieldFor(p,key=p.map){const [w,e,so,n]=maps[key].bounds;return String.fromCharCode(65+Math.min(3,Math.floor((p.lon-w)/(e-w)*4)))+(Math.min(3,Math.floor((n-p.lat)/(n-so)*4))+1);}
const stepTitles=['Erdviertel','Karte wählen','Breite suchen','Länge suchen','Ort prüfen'];
function stepText(){const p=cityData[s.city],q=quarter(p.lat,p.lon),named=s.mode!=='coords';
 const texts=[
  named?`Suche <b>${p.name}</b> im alphabetischen Ortsregister. Prüfe das Land: <b>${p.country}</b>. Der Registereintrag führt zur Karte und zum Suchfeld. Der bekannte Grad hilft dir beim Kontrollieren.`:`Zerlege die Angabe: <span class="aw-lat">${latText(p.lat)} = Breite</span>, <span class="aw-lon">${lonText(p.lon)} = Länge</span>. Das ist das <b>${q.name}</b>. Suche dieses Gebiet auf der Weltkarte.`,
  `Von der Weltkarte zur genaueren Karte: <b>${maps[p.map].name}</b>. Im echten Atlas findest du die passende Karte im Inhaltsverzeichnis, Kartenübersichtsplan oder Register. Seitenzahlen hängen von der Atlasausgabe ab.`,
  `Suche <b>${latText(p.lat)}</b> am Kartenrand und folge dem <span class="aw-lat">blauen Breitenkreis</span>. In der Lernkarte stehen die Breitengrade links. ${named?'Du gehst vom Ortszeichen zur Breitenangabe am Rand.':'Noch bleibt eine ganze Linie als Möglichkeit.'}`,
  `Suche <b>${lonText(p.lon)}</b> am Kartenrand und folge dem <span class="aw-lon">violetten Meridian</span>. ${named?'Kontrolliere, ob die Linie zum Ortszeichen und zur bekannten Angabe passt.':'Am Schnittpunkt mit dem Breitenkreis liegt die gesuchte Position.'}`,
  `Lies den Namen am Schnittpunkt: <b>${p.name}</b>, ${p.country}. Prüfe <b>beide Zahlen und beide Richtungen</b>. Bei gerundeten Koordinaten suchst du einen kleinen Bereich um den Punkt, keine exakte Adresse.`
 ];return texts[s.step];}
function atlasMap(){const p=cityData[s.city];return flatMap(s.step===0?'world':p.map,{quarters:s.step===0,city:p,lat:s.step>=2,lon:s.step>=3,point:s.step>=3,names:s.step>=4});}
function registerMap(p){
 let html=flatMap(p.map,{city:p,names:true}),[w,e,so,n]=maps[p.map].bounds;
 let a='';for(let i=0;i<=4;i++){let x=63+i*650/4,y=42+i*330/4;if(i<4)a+=`<text x="${x+650/8}" y="397" text-anchor="middle" font-size="17" font-weight="700" fill="#17394e">${String.fromCharCode(65+i)}</text><text x="733" y="${y+330/8+5}" font-size="17" font-weight="700" fill="#17394e">${i+1}</text>`;a+=`<path d="M${x} 42V372M63 ${y}H713" stroke="#17394e" stroke-width="1.5" stroke-dasharray="6 5"/>`;}
 const field=fieldFor(p);const col=field.charCodeAt(0)-65,row=Number(field[1])-1;
 a+=`<rect x="${63+col*650/4}" y="${42+row*330/4}" width="${650/4}" height="${330/4}" fill="#e6a129" fill-opacity=".2" stroke="#925b00" stroke-width="3"/>`;
 return html.replace('</svg>',a+'</svg>');
}
const gapItems=[
 {id:'parallel',label:'Lücke 1: Verlauf der Breitenkreise',words:['parallel'],tip:'Die Breitenkreise schneiden sich nicht. Sie haben überall dieselbe Richtung wie der Äquator.'},
 {id:'reference',label:'Lücke 2: Bezugslinie der Breitenkreise',words:['äquator','aequator'],tip:'Gesucht ist die Linie mit 0° geografischer Breite.'},
 {id:'north',label:'Lücke 3: Startpunkt des Meridians',words:['nordpol'],tip:'Gesucht ist der Pol bei 90° N.'},
 {id:'south',label:'Lücke 4: Endpunkt des Meridians',words:['südpol','suedpol'],tip:'Gesucht ist der Pol bei 90° S.'},
 {id:'largest',label:'Lücke 5: größter Breitenkreis',words:['äquator','aequator'],tip:'Dieser Breitenkreis liegt genau zwischen den beiden Polen und hat 0° Breite.'}
];
function checkGaps(values){return gapItems.map(item=>({id:item.id,ok:item.words.some(w=>normalize(w)===normalize(values[item.id]||'').replace(/[.!?]+$/,'')),empty:!String(values[item.id]||'').trim(),tip:item.tip}));}
function gapField(id){const item=gapItems.find(i=>i.id===id),result=s.gapFeedback?.find(i=>i.id===id);return `<span class="aw-gap-field"><label class="sr-only" for="aw-gap-${id}">${item.label}</label><input id="aw-gap-${id}" data-aw-gap="${id}" type="text" autocomplete="off" spellcheck="false" maxlength="40" value="${E(s.gaps[id]||'')}" placeholder="${id==='parallel'?'Wie?':'Welcher Begriff?'}" ${result?`aria-invalid="${!result.ok}" aria-describedby="aw-gap-feedback-${id}"`:''}>${result?`<span id="aw-gap-feedback-${id}" class="aw-gap-state" data-good="${result.ok}">${result.ok?'✓ Das passt.':result.empty?'Hier fehlt noch ein Wort.':'Das übe ich noch.'}</span>`:''}</span>`;}
function gapView(){const result=s.gapFeedback,count=result?.filter(r=>r.ok).length;return `<div class="aw-grid"><section class="aw-card"><span class="aw-kicker">Ergänzung zu deinem Arbeitsblatt</span><h2>Dein Lückentext: drei Sätze zum Gradnetz</h2><p>Ergänze die fünf Lücken. Du kannst die Wörter selbst schreiben oder vorher die Wort-Hilfe öffnen.</p><details data-aw-gap-help><summary>Wort-Hilfe öffnen</summary><div class="aw-chips"><span>Äquator</span><span>Nordpol</span><span>parallel</span><span>Südpol</span></div><p>Das Wort <b>Äquator</b> brauchst du zweimal. „Ae“ statt „Ä“ und „ue“ statt „ü“ werden ebenfalls erkannt.</p></details><form id="awGapForm"><ol class="aw-gap-list"><li>Die Breitenkreise verlaufen ${gapField('parallel')} zum ${gapField('reference')}.</li><li>Die Längenkreise verlaufen vom ${gapField('north')} zum ${gapField('south')}.</li><li>Der größte Breitenkreis ist der ${gapField('largest')}.</li></ol><div class="aw-controls"><button type="submit" class="aw-primary">Meine Lücken prüfen</button>${button('Lücken neu ausfüllen','gapReset')}${button(s.gapSolution?'Musterlösung ausblenden':'Musterlösung anzeigen','gapSolution')}</div></form>${termNote()}${result?`<div class="aw-feedback" role="status" data-good="${count===5}"><b>${count} von 5 Lücken passen.</b>${count===5?' Gut gemacht! Lies die drei vollständigen Sätze noch einmal.':' Du kannst deine Einträge verbessern und erneut prüfen.'}${result.filter(r=>!r.ok).map(r=>`<p><b>${E(gapItems.find(i=>i.id===r.id).label)}:</b> ${E(r.tip)}</p>`).join('')}${s.gapSeenSolution?'<p>Mit geöffneter Musterlösung übst du ohne neue Einträge im Lernfortschritt. Mit „Lücken neu ausfüllen“ startest du einen neuen Versuch.</p>':''}</div>`:''}${s.gapSolution?`<aside class="aw-callout"><h3>Musterlösung</h3><p>Die Breitenkreise verlaufen <b>parallel</b> zum <b>Äquator</b>.</p><p>Die Längenkreise verlaufen vom <b>Nordpol</b> zum <b>Südpol</b>.</p><p>Der größte Breitenkreis ist der <b>Äquator</b>.</p></aside>`:''}</section><div><details data-aw-gap-reference><summary>Erklärbilder als Hilfe anzeigen</summary><section class="aw-card aw-viewcard"><h3 class="aw-lat">Breitenkreise: parallel zum Äquator</h3>${globeGraphic(12,0,'lat',false)}<p>Der dicke blaue Kreis ist der Äquator. Die Breitenkreise werden zu den Polen hin kleiner. An jedem Pol bleibt nur ein Punkt.</p></section><section class="aw-card aw-viewcard"><h3 class="aw-lon">Meridiane: von Pol zu Pol</h3>${globeGraphic(0,0,'lon',false)}<p>Ein Meridian ist ein <b>halber Längenkreis</b>. Zwei gegenüberliegende Meridiane bilden einen ganzen Längenkreis. Ganze Längenkreise verlaufen durch beide Pole.</p></section></details></div></div>`;}

Object.assign(s,{mapZoom:1,globeZoom:1,gapHelpUsed:false,viewHelpUsed:false,quarterHelpUsed:false,markIndex:0,markMap:cityData[0].map,markPoint:null,markFeedback:null,hintLevel:0,demonstrate:false,atlasMap:'world',registerIndex:0,registerSearch:'',registerChoice:'',registerMapChoice:'',registerField:'',registerResult:null,examAnswers:{},examPoint:null,examResult:null,stats:{}});
for(const key of ['Grundlagen','Erdviertel','Ansichten','Kartenarbeit','Atlasarbeit']){const v=persisted.stats?.[key]||{};s.stats[key]={attempts:Math.max(0,Number(v.attempts)||0),correct:Math.max(0,Number(v.correct)||0),assisted:Math.max(0,Number(v.assisted)||0)};}
function persistWorkshop(){try{localStorage.setItem('geo-atlaswerkstatt-v1',JSON.stringify({done:[...s.done],stats:s.stats}))}catch{}}
function note(skill,ok,help=false){const v=s.stats[skill];v.attempts++;if(ok)v.correct++;if(help)v.assisted++;persistWorkshop();}
const close=(a,b,t)=>Number.isFinite(a)&&Math.abs(a-b)<=t;
function coordinateFeedback(lat,lon,target,tolerance=1){
 if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return {ok:false,code:'range',text:'Prüfe die Werte: Breite reicht bis 90°, Länge bis 180°. Wähle N/S und O/W passend dazu.'};
 if(close(lat,target.lat,tolerance)&&close(lon,target.lon,tolerance))return {ok:true,code:'correct',text:'Dein Punkt liegt am gesuchten Schnittpunkt. Gut abgelesen!'};
 if(close(lat,target.lon,tolerance)&&close(lon,target.lat,tolerance))return {ok:false,code:'swapped',text:'Du hast Breite und Länge vertauscht. Die Breite gehört zu N/S, die Länge zu O/W.'};
 if(close(lat,-target.lat,tolerance)&&close(lon,target.lon,tolerance))return {ok:false,code:'latitude-direction',text:'Prüfe Nord und Süd. Dein Punkt liegt auf der anderen Seite des Äquators.'};
 if(close(lat,target.lat,tolerance)&&close(lon,-target.lon,tolerance))return {ok:false,code:'longitude-direction',text:'Prüfe Ost und West. Dein Punkt liegt auf der anderen Seite des Nullmeridians.'};
 if(close(lat,target.lat,tolerance))return {ok:false,code:'longitude',text:'Die Breite passt bereits. Folge jetzt dem richtigen Meridian und kontrolliere seine Zahl sowie O/W.'};
 if(close(lon,target.lon,tolerance))return {ok:false,code:'latitude',text:'Die Länge passt bereits. Kontrolliere den Breitenkreis und die Angabe N/S.'};
 return {ok:false,code:'position',text:'Beginne am Kartenrand: Suche zuerst die Breite und folge ihr. Suche dann die Länge. Markiere den Schnittpunkt beider Linien.'};
}
function pointFromMap(x,y,key){const [w,e,so,n]=maps[key].bounds;if(x<63||x>713||y<42||y>372)return null;return {lat:round(n-(y-42)/330*(n-so)),lon:round(w+(x-63)/650*(e-w))};}
function normalWord(v){return normalize(v).replace(/[.!?]+$/,'').replace(/\s+/g,' ').trim();}
function resetAtlas(){stop();s.step=0;s.hintLevel=0;s.demonstrate=false;s.atlasMap='world';s.answer='';s.feedback=null;s.direction=s.mode==='nameLon'?'N':'O';}
function mapControls(){return `<div class="aw-controls aw-zoom-controls" aria-label="Kartenvergrößerung">${button('− Karte','mapZoom:-1','aria-label="Karte verkleinern"')}<output>${Math.round(s.mapZoom*100)} %</output>${button('+ Karte','mapZoom:1','aria-label="Karte vergrößern"')}${button('100 %','mapZoom:0')}</div>`;}
function mapOptions(value,world=true){return Object.entries(maps).filter(([k])=>world||k!=='world').map(([k,m])=>`<option value="${k}" ${value===k?'selected':''}>${m.name}</option>`).join('');}
function pickedText(p){return p?coord(p.lat,p.lon):'Noch kein Punkt markiert.';}
function pointPad(type,p){return `<div class="aw-point-pad"><p class="aw-muted">Antippen oder mit den Richtungstasten verschieben. Du kannst die vier Tasten auch mit Tab erreichen.</p><div class="aw-controls">${button('↑ Norden',type+'Move:N')}${button('← Westen',type+'Move:W')}${button('→ Osten',type+'Move:O')}${button('↓ Süden',type+'Move:S')}</div><p role="status" class="aw-result">Dein Punkt: ${pickedText(p)}</p></div>`;}
function markView(){const p=cityData[s.markIndex];return `<section class="aw-card"><span class="aw-kicker">Selbst markieren · ${s.markIndex+1} von ${cityData.length} Orten</span><h2>Wo liegt der gesuchte Schnittpunkt?</h2><p>Setze selbst einen Punkt auf die Karte. Die Ortsnamen und Lösungslinien bleiben verborgen.</p><div class="aw-stat">${coord(p.lat,p.lon)}</div><label for="awMarkExample">Aufgabe wählen</label><select id="awMarkExample" data-aw-mark-example>${cityData.map((p,i)=>`<option value="${i}" ${i===s.markIndex?'selected':''}>Aufgabe ${i+1} · ${quarter(p.lat,p.lon).name}</option>`).join('')}</select><label for="awMarkMap">Karte für deinen Versuch</label><select id="awMarkMap" data-aw-mark-map>${mapOptions(s.markMap)}</select>${mapControls()}${flatMap(s.markMap,{pick:'mark',marker:s.markPoint})}${pointPad('mark',s.markPoint)}<div class="aw-controls">${button('Meinen Punkt prüfen','markCheck','class="aw-primary"')}${button('Neue Ortsaufgabe →','markNext')}${button('Lösung vergleichen','markSolution')}</div>${feedback(s.markFeedback)}${s.markSolution?`<details open><summary>Vergleich mit der Lösung</summary><p>${p.name}, ${p.country}: ${coord(p.lat,p.lon)}. Der nächste Versuch startet wieder ohne Lösung.</p>${flatMap(p.map,{city:p,lat:true,lon:true,point:true,names:true,onlyCity:p.id})}</details>`:''}<p class="aw-muted">Ablesetoleranz: 1° auf einer Regionalkarte, 3° auf der Weltkarte. Für eine feinere Markierung kannst du die Karte vergrößern. Die Lösung wird vor dem Prüfen nicht angezeigt.</p></section>`;}
function atlasView(){const p=cityData[s.city],isLat=s.mode==='nameLon',level=s.demonstrate?s.step+1:s.hintLevel,key=s.demonstrate?(s.step===0?'world':p.map):s.atlasMap;
 return `<section class="aw-card"><h2>Mit dem Atlas einen Ort finden</h2><p>20 Orte, drei Sucharten. Beginne mit einem eigenen Versuch. Die Tipps kannst du einzeln öffnen.</p><div class="aw-controls">${[['coords','Koordinaten → Ort'],['nameLat','Ortsname + Breite'],['nameLon','Ortsname + Länge']].map(([k,t])=>button(t,'mode:'+k,`aria-pressed="${s.mode===k}"`)).join('')}</div><label for="awExample">Ortsaufgabe</label><select id="awExample" data-aw-example>${cityData.map((p,i)=>`<option value="${i}" ${s.city===i?'selected':''}>Aufgabe ${i+1}${s.mode==='coords'?'':' · '+p.name+' ('+p.country+')'}</option>`).join('')}</select><div class="aw-stat">${task()}</div><div class="aw-controls">${button('Selbst üben','independent',`aria-pressed="${!s.demonstrate}"`)}${button('Geführten Suchweg ansehen','demonstrate',`aria-pressed="${s.demonstrate}"`)}</div></section><div class="aw-grid"><section class="aw-card"><h3>${s.demonstrate?'Gustav zeigt den Suchweg':'Deine Arbeitskarte'}</h3>${s.demonstrate?`<div class="aw-steps">${stepTitles.map((t,i)=>button(`${i+1}. ${t}`,'step:'+i,`aria-current="${s.step===i?'step':'false'}"`)).join('')}</div>`:`<label for="awAtlasMapChoice">Wähle selbst die passende Karte</label><select id="awAtlasMapChoice" data-aw-atlas-map>${mapOptions(key)}</select>`}${mapControls()}${flatMap(key,{city:p,quarters:s.demonstrate&&s.step===0,lat:key===p.map&&level>=3,lon:key===p.map&&level>=4,point:key===p.map&&level>=4,names:(s.mode!=='coords'&&key!=='world')||level>=5,onlyCity:p.id})}${s.demonstrate?`<div class="aw-feedback" role="status">${stepText()}</div><div class="aw-controls">${button('← Zurück','step:'+Math.max(0,s.step-1))}${button(s.step===4?'Von vorn':'Weiter →','step:'+(s.step===4?0:s.step+1))}${button(s.playing?'Suchweg anhalten':'Suchweg abspielen','play')}</div>`:`<div class="aw-controls">${button(s.hintLevel===0?'Tipp 1 öffnen':s.hintLevel<4?'Nächsten Tipp öffnen':'Lösung anzeigen','hintNext',s.hintLevel>=5?'disabled':'')}</div>${s.hintLevel?`<div class="aw-feedback" role="status">${hintText(p)}</div>`:'<p class="aw-muted">Noch keine Hilfe geöffnet. Erst den Kartenrand lesen, dann die Linien verfolgen.</p>'}`}<p class="aw-muted">Kartenrand und Gradlinien können im echten Atlas anders aussehen. Die Karten hier sind vereinfachte Lernmodelle.</p></section><div><section class="aw-card"><h3>Deine Antwort</h3><form id="awAnswerForm">${s.mode==='coords'?`<label for="awAnswer">Wie heißt die Stadt?</label><input id="awAnswer" data-aw-answer type="text" autocomplete="off" value="${E(s.answer)}" placeholder="Ortsname">`:`<label for="awAnswer">Fehlende ${isLat?'Breite':'Länge'} in Grad</label><div class="aw-fields"><input id="awAnswer" data-aw-answer type="text" inputmode="decimal" autocomplete="off" value="${E(s.answer)}" placeholder="z. B. 14,4"><select id="awDirection" data-aw-direction aria-label="Himmelsrichtung">${(isLat?['N','S']:['O','W']).map(d=>`<option ${s.direction===d?'selected':''}>${d}</option>`).join('')}</select></div>`}<div class="aw-controls"><button type="submit" class="aw-primary">Antwort prüfen</button>${button('Nächste Ortsaufgabe →','nextCity')}</div></form>${feedback(s.feedback)}<details><summary>Register gezielt benutzen</summary><p>Bei bekanntem Ortsnamen helfen Land, Region, Kartenverweis und Planquadrat. Die Registerwerkstatt enthält alle 20 Orte.</p>${button('Zur Registerwerkstatt','view:register')}</details><div class="aw-callout">Ein Grad allein beschreibt normalerweise eine Linie. Ortsname + ein Grad: Ort über das Register finden, dann die fehlende Koordinate ablesen.</div><p class="aw-muted">Mit Hilfe gelöste Aufgaben werden in der Übungsstatistik entsprechend erfasst. Eine angezeigte Musterlösung gilt nicht als eigener Lösungsversuch.</p></section></div></div>`;
}
function hintText(p){return [null,`Lies die Richtungen: ${quarter(p.lat,p.lon).detail} Du suchst im ${quarter(p.lat,p.lon).name}.`,`Wähle die Regionalkarte <b>${maps[p.map].name}</b>. Vergleiche ihre Randwerte mit der Aufgabe.`,`Die blaue Linie zeigt den gesuchten Breitenkreis. Suche nun die Länge am Kartenrand.`,`Beide Gradlinien sind eingeblendet. Lies am Schnittpunkt den Ortsnamen; die Lösung ist noch nicht ausgeschrieben.`,`Lösung: <b>${p.name}</b> (${p.country}), ${coord(p.lat,p.lon)}.`][s.hintLevel];}
const registerCases=['frankfurt-main','frankfurt-oder','wellington','santiago','sanfrancisco','prag'];
function registerRows(search=''){const needle=normalWord(search);return [...cityData].sort((a,b)=>a.name.localeCompare(b.name,'de')).filter(p=>!needle||normalWord(p.name+' '+p.country+' '+p.region).includes(needle)).map(p=>`<tr><td>${E(p.name)}</td><td>${E(p.country)}<br><small>${E(p.region)}</small></td><td>${maps[p.map].code} · ${maps[p.map].name}</td><td>${fieldFor(p)}</td></tr>`).join('')||'<tr><td colspan="4">Kein Eintrag gefunden. Prüfe die Schreibweise oder suche nach Land/Region.</td></tr>';}
function registerView(){const p=cityData.find(p=>p.id===registerCases[s.registerIndex]);return `<section class="aw-card"><span class="aw-kicker">Atlasarbeit · Aufgabe ${s.registerIndex+1} / ${registerCases.length}</span><h2>Register, Karte und Planquadrat</h2><div class="aw-stat">Finde ${p.id.startsWith('frankfurt')?'Frankfurt':p.name} in <b>${p.country}, ${p.region}</b>.</div><p>1. Namen alphabetisch suchen. 2. Land und Region vergleichen. 3. Den Kartenverweis lesen. 4. Das Planquadrat aus Spalte und Zeile bilden.</p><label for="awRegisterSearch">Im Modellregister suchen</label><input id="awRegisterSearch" data-aw-register-search type="text" value="${E(s.registerSearch)}" placeholder="z. B. Frankfurt"><div class="aw-table-scroll"><table class="aw-register-table"><caption>Modellregister mit 20 Orten · Kartenbuchstaben gelten nur für diese App</caption><thead><tr><th>Ortsname</th><th>Land / Region</th><th>Kartenverweis</th><th>Suchfeld</th></tr></thead><tbody id="awRegisterRows">${registerRows(s.registerSearch)}</tbody></table></div><form id="awRegisterForm"><div class="aw-grid2"><div><label for="awRegisterPlace">Welcher Eintrag ist gemeint?</label><select id="awRegisterPlace" data-aw-register-place><option value="">Bitte wählen</option>${[...cityData].sort((a,b)=>a.name.localeCompare(b.name,'de')).map(p=>`<option value="${p.id}" ${s.registerChoice===p.id?'selected':''}>${p.name} · ${p.region}</option>`).join('')}</select></div><div><label for="awRegisterMap">Welche Karte schlägst du auf?</label><select id="awRegisterMap" data-aw-register-map><option value="">Bitte wählen</option>${mapOptions(s.registerMapChoice,false)}</select></div></div><label for="awRegisterField">Welches Planquadrat steht im Register?</label><input id="awRegisterField" data-aw-register-field type="text" maxlength="4" value="${E(s.registerField)}" placeholder="z. B. C3"><div class="aw-controls"><button class="aw-primary" type="submit">Meine Registersuche prüfen</button>${button('Nächste Registeraufgabe →','registerNext')}</div></form>${s.registerResult?`<div id="awRegisterResult" class="aw-feedback" role="status" data-good="${s.registerResult.ok}">${s.registerResult.text}</div>`:''}${s.registerMapChoice?`<h3>Deine ausgewählte Karte: ${maps[s.registerMapChoice].name}</h3>${mapControls()}${flatMap(s.registerMapChoice,{names:true,fields:true,fieldHighlight:/^[A-D][1-4]$/i.test(s.registerField.trim())?s.registerField.trim().toUpperCase():null})}`:''}<details><summary>Warum reicht „Frankfurt, Deutschland“ noch nicht?</summary><p>Frankfurt am Main liegt in Hessen, Frankfurt (Oder) in Brandenburg. Prüfe die Region oder einen anderen Zusatz im Namen. Ein Land allein löst hier die Mehrdeutigkeit noch nicht auf.</p></details><p class="aw-muted">Planquadrate sind keine Gradangaben. Seitenzahlen eines echten Atlanten hängen von Ausgabe und Auflage ab. Die Buchstaben E, N, S usw. in unserem Kartenverweis sind Modellkarten-Kennzeichen, keine Himmelsrichtungen.</p></section>`;}
function checkRegister(){const p=cityData.find(p=>p.id===registerCases[s.registerIndex]),place=s.registerChoice===p.id,map=s.registerMapChoice===p.map,field=s.registerField.trim().toUpperCase()===fieldFor(p),ok=place&&map&&field;
 s.registerResult={ok,text:`<p><b>Ortsname / Region:</b> ${place?'Das passt.':'Vergleiche Land und Region. Bei Frankfurt sind Hessen und Brandenburg entscheidend.'}</p><p><b>Kartenverweis:</b> ${map?'Die Karte passt.':'Lies den Verweis in der passenden Registerzeile noch einmal.'}</p><p><b>Planquadrat:</b> ${field?'Das Suchfeld passt.':'Nimm den Buchstaben für die Spalte und die Zahl für die Zeile aus derselben Registerzeile.'}</p>`};note('Atlasarbeit',ok);if(ok)mark('register:'+p.id);renderHere();}
const EXAM_STORE='geo-atlas-exam-v2';
function loadExamDraft(){try{const d=JSON.parse(localStorage.getItem(EXAM_STORE)||'null');if(d?.version!==2||!d.answers||typeof d.answers!=='object')return;
 s.examAnswers=Object.fromEntries(Object.entries(d.answers).filter(([k,v])=>typeof k==='string'&&k.length<60&&typeof v==='string').map(([k,v])=>[k,v.slice(0,600)]));
 s.examPoint=d.point&&Number.isFinite(d.point.lat)&&Number.isFinite(d.point.lon)&&Math.abs(d.point.lat)<=90&&Math.abs(d.point.lon)<=180?d.point:null;
 s.examIndex=Math.max(0,Math.min(9,Number(d.index)||0));s.examActive=!!d.active;s.examSubmitted=!!d.submitted;s.examRecorded=!!d.submitted;
 if(s.examSubmitted)s.examResult=gradeExam(s.examAnswers,s.examPoint);
 }catch{s.examStorageOk=false;}}
function saveExamDraft(){try{localStorage.setItem(EXAM_STORE,JSON.stringify({version:2,answers:s.examAnswers,point:s.examPoint,index:s.examIndex,active:s.examActive,submitted:s.examSubmitted}));s.examStorageOk=true;}catch{s.examStorageOk=false;}const saved=document.getElementById('awExamSaveStatus');if(saved)saved.textContent=s.examStorageOk?'Dein Versuch wird auf diesem Gerät zwischengespeichert.':'Zwischenspeichern ist in diesem Browser nicht möglich. Lass die Seite geöffnet, bis du fertig bist.';const label=document.getElementById('awExamComplete');if(label)label.textContent=window.AW_DATA.exam.filter(examAnswered).length+' von 10 Aufgaben vollständig bearbeitet'+(s.examSubmitted?' · Versuch abgeschlossen':'');}
Object.assign(s,{examIndex:0,examActive:false,examSubmitted:false,examRecorded:false,examResetConfirm:false,examStorageOk:true});
function scoreText(value){return Number(value).toLocaleString('de-DE',{maximumFractionDigits:1});}
function gradeExam(answers,point){return window.AW_DATA.exam.map(q=>{
 const parts=[];let code='answer';
 if(q.kind==='map'){
  const valid=point&&Number.isFinite(point.lat)&&Number.isFinite(point.lon)&&Math.abs(point.lat)<=90&&Math.abs(point.lon)<=180;
  const result=valid?coordinateFeedback(point.lat,point.lon,q.target,q.tolerance):{code:'empty'};code=result.code;
  parts.push({id:'pointLat',label:'Breite des markierten Punkts',points:valid&&close(point.lat,q.target.lat,q.tolerance)?1:0,max:1,answered:!!valid,expected:latText(q.target.lat)});
  parts.push({id:'pointLon',label:'Länge des markierten Punkts',points:valid&&close(point.lon,q.target.lon,q.tolerance)?1:0,max:1,answered:!!valid,expected:lonText(q.target.lon)});
 }else for(const f of q.fields){
  const raw=String(answers[f.id]??'').trim();let ok=false;
  if(f.kind==='number'){const value=number(raw,f.max);ok=value!==null&&Math.abs(value-f.target)<=(f.tolerance||0);}
  else if(f.kind==='field')ok=f.answers.some(v=>normalWord(v).replace(/\s/g,'')===normalWord(raw).replace(/\s/g,''));
  else ok=f.answers.some(v=>normalWord(v)===normalWord(raw));
  const expected=f.kind==='number'?scoreText(f.target):f.options?f.options.find(o=>o[0]===f.answers[0])?.[1]||f.answers[0]:f.answers[0];
  parts.push({id:f.id,label:f.label,points:ok?f.points:0,max:f.points,answered:raw!=='',expected});
 }
 const points=parts.reduce((n,p)=>n+p.points,0),max=parts.reduce((n,p)=>n+p.max,0);
 return {id:q.id,skill:q.skill,ok:points===max,points,max,parts,answered:parts.some(p=>p.answered),text:q.explanation,code};
 });}
function examAnswered(q){return q.kind==='map'?!!s.examPoint:q.fields.every(f=>String(s.examAnswers[f.id]??'').trim()!=='');}
function examModelGraphic(kind,label){const shape=kind==='parallel-pole'?'Ringe um den Pol':kind==='meridian-pole'?'Speichen zum Pol':kind==='parallel-side'?'waagerechte Linien':'Bögen zwischen den Polen';return viewModel(kind).replaceAll(BLUE,'#3f586b').replaceAll(PINK,'#3f586b').replace(/aria-label="[^"]*"/,`aria-label="${label}: ${shape}"`).replace(/<title>[\s\S]*?<\/title>/,`<title>${label}: ${shape}</title>`);}
function examField(f){const disabled=s.examSubmitted?'disabled':'';return `<div class="aw-exam-field"><label for="awExam-${f.id}">${E(f.label)} <small>(${scoreText(f.points)} P.)</small></label>${f.options?`<select id="awExam-${f.id}" data-aw-exam="${f.id}" ${disabled}><option value="">Bitte wählen</option>${f.options.map(([value,label])=>`<option value="${E(value)}" ${s.examAnswers[f.id]===value?'selected':''}>${E(label)}</option>`).join('')}</select>`:`<input id="awExam-${f.id}" data-aw-exam="${f.id}" type="text" autocomplete="off" maxlength="80" ${f.kind==='number'?'inputmode="decimal"':''} value="${E(s.examAnswers[f.id]||'')}" ${disabled}>`}</div>`;}
function examRegisterRows(){return ['frankfurt-main','frankfurt-oder','berlin','lissabon'].map(id=>cityData.find(p=>p.id===id)).map(p=>{const key=p.country==='Deutschland'?'germany':p.map;return {name:p.name,country:p.country,region:p.region,map:key,code:maps[key].code,field:fieldFor(p,key)};});}
function examRegisterTable(){return `<div class="aw-table-scroll"><table class="aw-register-table"><caption>Modellregister für Aufgabe 9 · Kartenkennzeichen gelten nur in diesem Test</caption><thead><tr><th>Ort</th><th>Land / Region</th><th>Karte</th><th>Suchfeld</th></tr></thead><tbody>${examRegisterRows().map(p=>`<tr><td>${p.name}</td><td>${p.country}<br>${p.region}</td><td>${p.code} · ${maps[p.map].name}</td><td>${p.field}</td></tr>`).join('')}</tbody></table></div>`;}
function examQuestion(q){
 let art='';
 if(q.kind==='views')art=`<div class="aw-grid2 aw-exam-models">${q.models.map((kind,i)=>`<figure><figcaption>Modell ${i===0?'A':'B'}</figcaption>${examModelGraphic(kind,'Modell '+(i===0?'A':'B'))}</figure>`).join('')}</div>`;
 if(q.kind==='map')art=`${mapControls()}${flatMap(q.map,{pick:s.examSubmitted?null:'exam',marker:s.examPoint,city:q.target,point:s.examSubmitted})}${s.examSubmitted?`<p>Gelber Punkt: Lösung · Kreuz: deine Markierung</p>`:pointPad('exam',s.examPoint)}<p class="aw-muted">Breite und Länge werden einzeln bewertet. Pro Achse ist eine Ableseabweichung bis 1° erlaubt.</p>`;
 if(q.kind==='readpoint')art=`${mapControls()}${flatMap(q.map,{marker:q.target})}<p class="aw-muted">Der markierte Punkt ist P. Nenne zuerst seine Breite, dann seine Länge.</p>`;
 if(q.kind==='register')art=examRegisterTable()+`<details><summary>Die Modellkarte zu diesem Register ansehen</summary>${flatMap('germany',{fields:true})}</details>`;
 if(q.kind==='longitude')art=`${mapControls()}${flatMap(q.map,{names:true,onlyCity:q.city})}`;
 const result=s.examSubmitted?s.examResult.find(r=>r.id===q.id):null;
 return `<section class="aw-card aw-exam-question"><span class="aw-kicker">${q.skill} · 2 Punkte</span><h2>${s.examIndex+1}. ${E(q.title)}</h2><p class="aw-exam-instruction">${E(q.question)}</p>${art}${q.fields?`<div class="aw-grid2 aw-exam-fields">${q.fields.map(examField).join('')}</div>`:''}${q.id==='lisbon'?`<details><summary>Zusatzgedanke ohne Punkte</summary><label for="awExamReason">Warum bestimmt ein Breitengrad allein normalerweise noch keinen eindeutigen Ort?</label><textarea id="awExamReason" data-aw-exam="reason" maxlength="600" ${s.examSubmitted?'disabled':''}>${E(s.examAnswers.reason||'')}</textarea>${s.examSubmitted?'<p>Auf einem Breitenkreis liegen viele Punkte. Normalerweise brauchst du auch die Länge. Vergleiche deine Begründung selbst; sie wird nicht automatisch benotet.</p>':''}</details>`:''}${result?examQuestionResult(result):''}</section>`;
}
function examQuestionResult(r){return `<div class="aw-feedback" role="status" data-good="${r.ok}"><b>${scoreText(r.points)} von ${scoreText(r.max)} Punkten${!r.answered?' · noch nicht beantwortet':''}</b><ul>${r.parts.map(p=>`<li>${E(p.label)}: ${scoreText(p.points)} / ${scoreText(p.max)}${p.points<p.max?' · Lösung: '+E(p.expected):' · passt'}</li>`).join('')}</ul><p>${E(r.text)}</p>${r.code==='swapped'?'<p>Du hast die Koordinaten vertauscht. Breite gehört zu N/S, Länge zu O/W.</p>':''}</div>`;}
function examView(){const questions=window.AW_DATA.exam,complete=questions.filter(examAnswered).length;
 const head=`<section class="aw-card"><span class="aw-kicker">Teil A · Wissen und Karten · 20 Punkte</span><h2>Zeig, was du schon kannst.</h2><p>Teil A enthält zehn Aufgaben in fünf Bereichen. Teil B enthält zusätzlich die Zeichen- und Beschriftungsaufgaben aus deinen Unterrichtsskizzen. Jeder Bereich zählt vier Punkte. Du kannst zurückblättern und Antworten verbessern. Lösungen erscheinen erst nach der Abgabe.</p><p class="aw-muted">Richtwert: 20–25 Minuten, ohne Zeitdruck.</p><p id="awExamSaveStatus" class="aw-muted" aria-live="polite">${s.examStorageOk?"Dein Versuch wird auf diesem Gerät zwischengespeichert.":"Zwischenspeichern ist in diesem Browser nicht möglich. Lass die Seite geöffnet, bis du fertig bist."}</p><div class="aw-controls">${button('Teil B · Zeichnen wie auf den Skizzen','view:sketch')}${button(s.examActive?'Neuen Versuch beginnen':'Test beginnen','examNew','class="aw-primary"')}${pdfLinks(s.examSubmitted)}</div>${s.examResetConfirm?`<div class="aw-callout">Es gibt bereits einen Versuch. Möchtest du mit leeren Antworten neu beginnen?<div class="aw-controls">${button('Mit leeren Antworten neu beginnen','examConfirmReset')}${button('Bisherigen Versuch behalten','examKeep')}</div></div>`:''}</section>`;
 if(!s.examActive)return head+`<section class="aw-card"><h3>Das erwartet dich</h3><ol><li>Bezugslinien und Gradangaben</li><li>Alle vier Erdviertel</li><li>Vier Ansichten der Gradlinien</li><li>Punkt markieren und Koordinaten ablesen</li><li>Register benutzen und einen fehlenden Grad finden</li></ol><p>Bei mehrteiligen Aufgaben kannst du Teilpunkte sammeln. Die freie Zusatzbegründung wird nicht automatisch benotet.</p></section>`;
 return head+`<section class="aw-card aw-exam-progress"><p id="awExamComplete" role="status">${complete} von 10 Aufgaben vollständig bearbeitet${s.examSubmitted?' · Versuch abgeschlossen':''}</p><nav class="aw-exam-numbers" aria-label="Aufgaben des Tests">${questions.map((q,i)=>button(`${i+1}${examAnswered(q)?' ✓':''}`,'examGo:'+i,`aria-label="Aufgabe ${i+1}${examAnswered(q)?', bearbeitet':''}" aria-current="${i===s.examIndex?'step':'false'}"`)).join('')}</nav></section><form id="awExamForm">${examQuestion(questions[s.examIndex])}<section class="aw-card aw-controls">${button('← Vorherige Aufgabe','examGo:'+Math.max(0,s.examIndex-1),s.examIndex===0?'disabled':'')}${s.examIndex<9?button('Nächste Aufgabe →','examGo:'+(s.examIndex+1),'class="aw-primary"'):s.examSubmitted?'':'<button type="submit" class="aw-primary">Test abgeben und auswerten</button>'}${s.examSubmitted?button('Gesamtergebnis ansehen','examShowResult'):''}</section></form>${s.examSubmitted?examResults():''}`;
}
function pdfLinks(withSolutions=true){const p=window.AW_PDFS;if(!p)return '<span class="aw-muted">Druckdateien werden geladen.</span>';const current=p.version==='2026-10-27-v6';if(!current)return '<span class="aw-callout">Diese App enthält eine ältere Druckdatei. Öffne die aktualisierte App für den neunseitigen Test.</span>';return `<a class="aw-download" href="${p.test}" download="${p.testName}" title="Fassung 27.10.2026, ${p.testPages} Seiten">Aktueller Test · ${p.testPages} Seiten · 27.10.2026</a>${withSolutions?`<a class="aw-download" href="${p.solutions}" download="${p.solutionsName}">Aktuelle Lösungen · ${p.solutionPages} Seiten</a>`:''}`;}
function examResults(){const r=s.examResult,total=r.reduce((n,q)=>n+q.points,0),dest={Grundlagen:'gaps',Erdviertel:'quarters',Ansichten:'views',Kartenarbeit:'mark',Atlasarbeit:'register'},skills=window.AW_DATA.examMeta.skills.map(skill=>({skill,points:r.filter(q=>q.skill===skill).reduce((n,q)=>n+q.points,0)}));
 return `<section class="aw-card" id="awExamResults" tabindex="-1"><h2>Dein Ergebnis: ${scoreText(total)} von 20 Punkten</h2><p>${total===20?'Alle Teilaufgaben passen. Gut gemacht!':'Du erhältst Punkte für alle passenden Teilantworten. Hier siehst du, wo du schon sicher bist und was du gezielt weiterüben kannst.'}</p><div class="aw-table-scroll"><table class="aw-register-table"><thead><tr><th>Bereich</th><th>Punkte</th><th>Weiterlernen</th></tr></thead><tbody>${skills.map(v=>`<tr><td>${v.skill}</td><td>${scoreText(v.points)} / 4</td><td>${v.points<4?button(v.skill+' weiterüben','view:'+dest[v.skill]):'Das klappt schon gut.'}</td></tr>`).join('')}</tbody></table></div><div class="aw-controls">${r.filter(q=>!q.ok).map(q=>button('Aufgabe '+(r.indexOf(q)+1)+' ansehen','examGo:'+r.indexOf(q))).join('')}</div><p class="aw-muted">Die Antworten dieses abgeschlossenen Versuchs bleiben unverändert. Für einen neuen Versuch wählst du oben „Neuen Versuch beginnen“. Die Punkte sind ein Lernhinweis, keine automatisch vergebene Schulnote.</p>${pdfLinks(true)}</section>`;
}
function finishExam(){if(s.examSubmitted)return;s.examResult=gradeExam(s.examAnswers,s.examPoint);s.examSubmitted=true;if(!s.examRecorded){for(const r of s.examResult)note(r.skill,r.ok);s.examRecorded=true;}saveExamDraft();renderHere();document.getElementById('awExamResults')?.focus();}
function beginNewExam(){s.examAnswers={};s.examPoint=null;s.examResult=null;s.examIndex=0;s.examActive=true;s.examSubmitted=false;s.examRecorded=false;s.examResetConfirm=false;saveExamDraft();renderHere();}
loadExamDraft();

// Zeichenteil nach den eingereichten Unterrichtsskizzen. Keine automatische Zeichenbewertung.
const SKETCH_STORE='geo-atlas-skizzen-v1';
const sketchPanels=[['globe','Erdkugel beschriften','globe'],['halves','Halbkugeln unterscheiden','halves'],['quarters','Vier Erdviertel eintragen','quarters'],['latSide','Breitenkreise · Blick vom Äquator','circle'],['latPole','Breitenkreise · Blick auf einen Pol','circle'],['lonSide','Meridiane · Blick vom Äquator','circle'],['lonPole','Meridiane · Blick auf einen Pol','circle'],['angle','Breitenwinkel · Seitenansicht','angle']];
let sketch={paths:{},texts:{},review:false,color:BLUE},sketchStorage=true,ink=null;
function cleanSketch(value){const out={paths:{},texts:{},review:value?.review===true,color:[BLUE,PINK].includes(value?.color)?value.color:BLUE};for(const [id] of sketchPanels){const paths=value?.paths?.[id];out.paths[id]=Array.isArray(paths)?paths.slice(0,100).filter(p=>p&&[BLUE,PINK].includes(p.color)&&Array.isArray(p.points)&&p.points.length<=500&&p.points.every(x=>Array.isArray(x)&&x.length===2&&x.every((n,i)=>Number.isFinite(n)&&n>=0&&n<=(i===0?480:300)))):[];}for(const [k,v] of Object.entries(value?.texts||{}))if(/^[a-zA-Z0-9]+$/.test(k)&&typeof v==='string')out.texts[k]=v.slice(0,1500);return out;}
try{sketch=cleanSketch(JSON.parse(localStorage.getItem(SKETCH_STORE)||'null'));}catch{sketchStorage=false;sketch=cleanSketch(null);}
function saveSketch(){try{localStorage.setItem(SKETCH_STORE,JSON.stringify(sketch));sketchStorage=true;}catch{sketchStorage=false;}const el=document.getElementById('awSketchSaved');if(el)el.textContent=sketchStorage?'Deine Zeichnungen und Texte sind auf diesem Gerät gespeichert.':'Speichern ist hier nicht möglich. Übertrage deine Zeichnung vor dem Schließen auf Papier.';}
function inkPath(p){return `<path d="${p.points.map((xy,i)=>(i?'L':'M')+xy.join(',')).join(' ')}${p.points.length===1?'l0.1,0.1':''}" fill="none" stroke="${p.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;}
function sketchBase(type){const circle=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r}"/>`;if(type==='globe')return circle(240,150,115)+`<g stroke="${BLUE}"><path d="M125 150H355M132 110H348M132 190H348M158 70H322M158 230H322"/></g><g stroke="${PINK}"><ellipse cx="240" cy="150" rx="35" ry="115"/><ellipse cx="240" cy="150" rx="75" ry="115"/><path d="M240 35V265"/></g>`;return type==='halves'?circle(128,150,94)+circle(352,150,94):type==='quarters'?'<path d="M240 35V270M55 150H425"/><text x="245" y="27">Nullmeridian</text><text x="340" y="145">Äquator</text>':circle(240,150,110);}
function sketchBoard(id,title,type){return `<div class="aw-sketch-board"><h3>${title}</h3><svg viewBox="0 0 480 300" data-aw-sketch="${id}" role="img" aria-label="Zeichenfläche: ${title}"><g fill="none" stroke="currentColor" stroke-width="1.5" class="aw-sketch-template">${sketchBase(type)}</g><g data-aw-ink>${(sketch.paths[id]||[]).map(inkPath).join('')}</g></svg><div class="aw-controls">${button('Letzten Strich zurücknehmen','sketchUndo:'+id,(sketch.paths[id]||[]).length?'':'disabled')}</div><label for="awSketch-${id}">Beschriftung oder Beschreibung deiner Zeichnung</label><textarea id="awSketch-${id}" data-aw-sketch-text="${id}" maxlength="1500" rows="2">${E(sketch.texts[id]||'')}</textarea></div>`;}
function originalScene(key){const scene=window.AW_DATA.notes.scenes[key];const attr=(name,value)=>` ${name}="${E(value)}"`;const paint=i=>{const stroke=i.color||'none',fill=i.fill||'none',style=` fill="${fill}" stroke="${stroke}" stroke-width="${i.width||1}"`;if(i.tag==='text')return `<text x="${i.x}" y="${i.y}" text-anchor="middle" fill="${i.color}" font-size="${i.size}" font-weight="${i.bold?700:400}"${i.rotate?` transform="rotate(${i.rotate} ${i.x} ${i.y})"`:''}${i.halo?' stroke="#fff" stroke-width="4" paint-order="stroke" stroke-linejoin="round"':''}>${E(i.text)}</text>`;if(i.tag==='polyline')return `<${i.close?'polygon':'polyline'} points="${i.points.map(p=>p.join(',')).join(' ')}"${style}/>`;const keys=i.tag==='circle'?['cx','cy','r']:i.tag==='ellipse'?['cx','cy','rx','ry']:['x1','y1','x2','y2'];return `<${i.tag}${keys.map(k=>attr(k,i[k])).join('')}${style}/>`;};return `<div class="aw-original-scroll" tabindex="0" role="region" aria-label="Unterrichtsskizze; bei Bedarf seitlich verschieben"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${scene.w} ${scene.h}" role="img" aria-label="${E(({hemispheres:'Nordhalbkugel, Südhalbkugel, Westhalbkugel und Osthalbkugel mit Äquator, Nullmeridian und Polen',globe:'Gradnetz mit beschrifteten Breitenkreisen, Meridianen, Äquator, Nullmeridian und Polen',quarters:'Die vier Erdviertel',views:'Vier Felder mit Breiten- und Längenkreisen',angle:'Halbkugel mit Nordpol, Südpol, Äquator und Erdmittelpunkt'})[key]||'Beschriftungsaufgabe nach der Unterrichtsskizze')}">${scene.items.map(paint).join('')}</svg></div>`;}
function termNote(){return '<p class="aw-muted">Begriff aus deiner Vorlage: „Längenkreise“. Fachlich ist die Strecke von Pol zu Pol ein Meridian oder Längenhalbkreis. Zwei gegenüberliegende Meridiane bilden einen ganzen Längenkreis.</p>';}
function notesView(){return `<section class="aw-card"><span class="aw-kicker">Deine vier hochgeladenen Vorlagen</span><h2>Deine Unterrichtsskizzen – vollständig beschriftet</h2><p>Die Anordnung folgt deinen Fotos: erst Halbkugeln und Gradnetz, dann Erdviertel und vier Ansichten, danach Atlasarbeit und die drei Merksätze.</p><div class="aw-controls">${button('Beschriftungen im Test selbst eintragen','view:sketch')}${button('Lückentext üben','view:gaps')}</div></section><section class="aw-card"><h2>1. Nordhalbkugel, Südhalbkugel, Westhalbkugel und Osthalbkugel</h2>${originalScene('hemispheres')}<p>Wie in deiner Zeichnung: Der <b>Äquator</b> trennt Nord- und Südhalbkugel. In der zweiten Darstellung liegen West- und Osthälfte auseinander; der <b>Nullmeridian</b> steht zwischen ihnen. Die andere Grenze zwischen Ost und West liegt am 180°-Meridian auf der Rückseite.</p></section><section class="aw-card"><h2>2. Nordpol, Südpol, Äquator und Meridian</h2>${originalScene('globe')}${termNote()}<p>Die Datumsgrenze liegt ungefähr am <b>180°-Meridian</b>; sie weicht stellenweise davon ab.</p></section><section class="aw-card"><h2>3. Die vier Erdviertel</h2>${originalScene('quarters')}<p>Nullmeridian senkrecht, Äquator waagerecht: oben Nordwest- und Nordostviertel, unten Südwest- und Südostviertel.</p></section><section class="aw-card"><h2>4. Die vier Felder deiner zweiten Skizze</h2>${originalScene('views')}<p>Breitenkreise: vom Äquator Linien, vom Pol Ringe. Längenkreise beziehungsweise Meridiane: vom Äquator Bögen, vom Pol Speichen.</p></section><section class="aw-card"><h2>5. Deine Halbkugel mit Erdmittelpunkt</h2>${originalScene('angle')}<p>Der Äquator hat 0° Breite, der Nordpol 90° N, der Südpol 90° S. Die Achse reicht wie in deiner Skizze durch den Erdmittelpunkt zum Südpol. Auch der linke Rand des Äquators hat 0° Breite.</p></section><section class="aw-card"><h2>6. Atlasarbeit aus deiner Vorlage</h2><ol><li>Bei zwei Koordinaten: zuerst Weltkarte und Erdviertel bestimmen, dann eine passende Regionalkarte aufschlagen.</li><li>Breite am Kartenrand suchen und den Breitenkreis verfolgen.</li><li>Länge suchen und den Meridian verfolgen. Der Schnittpunkt ist der gesuchte Ort.</li><li>Bei Ortsname und einem Grad: Register benutzen, Karte und Planquadrat finden und die fehlende Koordinate ablesen.</li></ol><p>Deine Beispiele sind enthalten: Prag, Lissabon, San Francisco und Alice Springs. Prag liegt gerundet bei 50,1° N / 14,4° O, Lissabon bei 38,7° N / 9,1° W.</p><div class="aw-controls">${button('Suchwege selbst üben','view:atlas')}${button('Register benutzen','view:register')}</div></section><section class="aw-card"><h2>7. Die drei Sätze aus deinem Lückentext</h2>${window.AW_DATA.notes.sentences.map(t=>`<p>${E(t)}</p>`).join('')}${termNote()}${button('Genau diesen Lückentext ausfüllen','view:gaps','class="aw-primary"')}</section>`;}
function originalLabelFields(){return `<div class="aw-grid2">${window.AW_DATA.notes.labels.map(([id])=>`<div><label for="awOriginal-${id}">Beschriftung ${id}</label><input id="awOriginal-${id}" data-aw-sketch-text="label${id}" maxlength="80" value="${E(sketch.texts['label'+id]||'')}"></div>`).join('')}</div>`;}
function sketchGap(id){return `<input aria-label="${E(gapItems.find(q=>q.id===id).label)}" data-aw-sketch-text="gap${id}" value="${E(sketch.texts['gap'+id]||'')}" maxlength="80">`;}
function sketchView(){const board=id=>sketchBoard(...sketchPanels.find(p=>p[0]===id));return `<section class="aw-card"><span class="aw-kicker">Teil B · Beschriften, Zeichnen und Lückentext</span><h2>Test nach deinen Unterrichtsskizzen</h2><p>Die Halbkugeln und Linien sind wie in deiner Vorlage vorgezeichnet. Trage die Beschriftungen selbst ein. In der Vier-Felder-Aufgabe zeichnest du die Linien. Der Zeichenteil wird anhand der Musterlösung geprüft und gehört nicht zu den automatisch ermittelten 20 Punkten aus Teil A.</p><div class="aw-controls">${button('Teil A · Wissen und Karten','view:exam')}${pdfLinks(sketch.review)}${button('Blauer Stift','sketchColor:blue',`aria-pressed="${sketch.color===BLUE}"`)}${button('Violetter Stift','sketchColor:purple',`aria-pressed="${sketch.color===PINK}"`)}</div><p id="awSketchSaved" role="status">${sketchStorage?'Deine Zeichnungen und Texte sind auf diesem Gerät gespeichert.':'Speichern ist hier nicht möglich. Übertrage deine Antworten auf Papier.'}</p></section><section class="aw-card"><h2>11. Beschrifte die Halbkugeln wie auf dem Foto</h2><p>Schreibe die acht Begriffe zu den Buchstaben A bis H. Achte auf die Pole, die vier Halbkugeln und die beiden Trennlinien.</p>${originalScene('hemispheresTest')}<details><summary>Wortliste aus deiner Vorlage als Hilfe</summary><p>Äquator · Nordhalbkugel · Nordpol · Nullmeridian · Osthalbkugel · Südhalbkugel · Südpol · Westhalbkugel</p></details>${originalLabelFields()}<p>Ergänze zu deinem Gradnetz: Welche Linien sind Breitenkreise, welche sind Längenkreise beziehungsweise Meridiane?</p>${board('globe')}</section><section class="aw-card"><h2>12. Trage die vier Erdviertel ein</h2><p>Wie auf deiner ersten Skizze: Äquator waagerecht, Nullmeridian senkrecht. Norden ist oben.</p>${board('quarters')}</section><section class="aw-card"><h2>13. Die vier Felder aus deiner zweiten Skizze</h2><p>Obere Reihe: Breitenkreise. Untere Reihe: Längenkreise beziehungsweise Meridiane. Linke Spalte: Blick auf den Äquator. Rechte Spalte: Blick auf den Nord- oder Südpol. Zeichne die Linien in jedes Feld.</p><div class="aw-sketch-four">${['latSide','latPole','lonSide','lonPole'].map(board).join('')}</div></section><section class="aw-card"><h2>14. Halbkugel, Pole und Erdmittelpunkt</h2><p>Beschrifte Nordpol, Südpol, Äquator und Erdmittelpunkt. Ergänze die Breitenangaben 0°, 90° N und 90° S. Die Achse und Äquatorebene sind wie auf deinem Foto vorgezeichnet.</p>${originalScene('angleTest')}<label for="awSketch-angle">Deine Beschriftungen zur Halbkugel</label><textarea id="awSketch-angle" data-aw-sketch-text="angle" rows="3" maxlength="1500">${E(sketch.texts.angle||'')}</textarea></section><section class="aw-card"><h2>15. Der Lückentext aus deiner Vorlage</h2><div class="aw-original-gaps"><p>Die Breitenkreise verlaufen ${sketchGap('parallel')} zum ${sketchGap('reference')}.</p><p>Die Längenkreise verlaufen vom ${sketchGap('north')} zum ${sketchGap('south')}.</p><p>Der größte Breitenkreis ist der ${sketchGap('largest')}.</p></div>${termNote()}</section><section class="aw-card"><p>Erst selbst bearbeiten, dann vergleichen. Nach dem Öffnen der Musterlösung gilt dieser Teil als mit Hilfe bearbeitet.</p>${button(sketch.review?'Musterlösung ist geöffnet':'Mit der beschrifteten Vorlage vergleichen','sketchReview',sketch.review?'disabled':'class="aw-primary"')}${sketch.review?sketchSolutions():''}</section>`;}
function sketchSolutions(){return `<div class="aw-feedback"><h2>Musterlösung zu deinen Vorlagen</h2><h3>11. Die acht Beschriftungen</h3>${originalScene('hemispheres')}<p>${window.AW_DATA.notes.labels.map(([id,text])=>`${id}: ${text}`).join(' · ')}</p>${originalScene('globe')}<h3>12. Erdviertel</h3>${originalScene('quarters')}<h3>13. Vier Felder</h3>${originalScene('views')}<h3>14. Halbkugel mit Polen</h3>${originalScene('angle')}<h3>15. Die vollständigen Sätze</h3>${window.AW_DATA.notes.sentences.map(t=>`<p>${E(t)}</p>`).join('')}${termNote()}</div>`;}

function sketchXY(e,svg){const box=svg.getBoundingClientRect();return [round(Math.max(0,Math.min(480,(e.clientX-box.left)/box.width*480))),round(Math.max(0,Math.min(300,(e.clientY-box.top)/box.height*300)))];}
ROOT.addEventListener('pointerdown',e=>{const svg=e.target.closest('svg[data-aw-sketch]');if(!svg||e.button>0)return;e.preventDefault();const id=svg.dataset.awSketch;if((sketch.paths[id]||[]).length>=100){const note=document.getElementById('awSketchSaved');if(note)note.textContent='100 Striche erreicht. Nimm einen Strich zurück oder ergänze die Beschreibung.';return;}svg.setPointerCapture(e.pointerId);const path={color:sketch.color,points:[sketchXY(e,svg)]};(sketch.paths[id]??=[]).push(path);ink={svg,path,pointer:e.pointerId};svg.querySelector('[data-aw-ink]').insertAdjacentHTML('beforeend',inkPath(path));});
ROOT.addEventListener('pointermove',e=>{if(!ink||ink.pointer!==e.pointerId||ink.path.points.length>=500)return;e.preventDefault();const p=sketchXY(e,ink.svg),last=ink.path.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])<1)return;ink.path.points.push(p);ink.svg.querySelector('[data-aw-ink]').lastElementChild.setAttribute('d',ink.path.points.map((xy,i)=>(i?'L':'M')+xy.join(',')).join(' '));});
function finishInk(e){if(!ink||ink.pointer!==e.pointerId)return;const id=ink.svg.dataset.awSketch;ink=null;saveSketch();const b=ROOT.querySelector(`[data-aw="sketchUndo:${id}"]`);if(b)b.disabled=false;}
ROOT.addEventListener('pointerup',finishInk);ROOT.addEventListener('pointercancel',finishInk);
ROOT.addEventListener('input',e=>{const key=e.target.dataset.awSketchText;if(key){sketch.texts[key]=e.target.value;saveSketch();}});

// Zusammenhängende Klassenarbeit zu allen 18 Aufgaben der PDF vom 27.10.2026.
const CW_STORE='geo-klassenarbeit-18-v1';
const cwText=(id,label,answers,points=1)=>({id,label,kind:'text',answers,points});
const cwNumber=(id,label,target,max=90)=>({id,label,kind:'number',target,max,points:1});
const cwQuarters=(prefix)=>[['nw','Nordwestviertel'],['no','Nordostviertel'],['sw','Südwestviertel'],['so','Südostviertel']].map(([code,text],i)=>cwText(prefix+i,`${i+1}. ${prefix==='cross'?(i<2?'oben':'unten')+' '+(i%2?'rechts':'links'):'Bereich '+(i+1)}`,[text,code]));
const cwBoards={latSide:['Breitenkreise · Seitenansicht','circle'],latPole:['Breitenkreise · Draufsicht auf den Pol','circle'],lonSide:['Meridiane · Seitenansicht','circle'],lonPole:['Meridiane · Draufsicht auf den Pol','circle'],gLat:['a) Breitenkreise einzeichnen','circle'],gLon:['b) Meridiane einzeichnen','circle'],gBoth:['c) Beide Linienarten und Schnittpunkt','circle']};
const cwRubrics={viewsdraw:[['latSide','Breitenkreise seitlich: waagerechte Linien'],['latPole','Breitenkreise vom Pol: konzentrische Ringe'],['lonSide','Meridiane seitlich: Bögen zwischen beiden Polen'],['lonPole','Meridiane vom Pol: Speichen zum Mittelpunkt']],drawglobe:[['latEquator','Äquator mittig und beschriftet'],['latMore','Weitere Breitenkreise parallel; Pole bleiben frei'],['lonPoles','Meridiane verbinden beide Pole'],['lonZero','Nullmeridian passend beschriftet'],['bothKinds','Beide Linienarten unterscheidbar'],['intersection','Schnittpunkt markiert und Linien benannt']],house:[['reason','Begründung nennt ein zur Ansicht passendes Merkmal']]};
const cwTasks=[...window.AW_DATA.exam,
{id:'halflabels',kind:'labels',title:'Halbkugeln und Pole beschriften',skill:'Beschriften',question:'Wie auf deinem Foto: Trage die acht Begriffe zu A bis H ein. Die Trennlinien und Pole sind vorgezeichnet.',fields:window.AW_DATA.notes.labels.map(([id,t])=>cwText('label'+id,'Beschriftung '+id,[t]))},
{id:'cross',kind:'cross',title:'Erdviertel an der Zeichnung',skill:'Erdviertel',question:'Norden ist oben. Benenne die vier Bereiche mit dem vollständigen Namen oder NO, NW, SO, SW.',fields:cwQuarters('cross')},
{id:'viewsdraw',kind:'draw',title:'Die vier Felder aus deiner Skizze',skill:'Zeichnen',question:'Zeichne nur die genannte Linienart. Links schaust du vom Äquator auf die Erde, rechts auf den Nord- oder Südpol.',boards:['latSide','latPole','lonSide','lonPole'],fields:[]},
{id:'polelabels',kind:'polelabels',title:'Halbkugel, Pole und Erdmittelpunkt',skill:'Beschriften',question:'Beschrifte die Halbkuppel und ergänze die Breitengrade. Die Achse reicht durch den Erdmittelpunkt weiter zum Südpol.',fields:[cwText('poleTop','Oben an der Achse',['Nordpol']),cwText('poleBottom','Unten an der Achse',['Südpol','Suedpol']),cwText('poleRight','Rechts an der waagerechten Ebene',['Äquator','Aequator']),cwText('poleCenter','Am schwarzen Punkt',['Erdmittelpunkt','Mittelpunkt der Erde']),cwNumber('northDegree','Breite am Nordpol: Gradzahl (N)',90),cwNumber('southDegree','Breite am Südpol: Gradzahl (S)',90),cwNumber('equatorDegree','Breite am Äquator: Gradzahl',0)]},
{id:'gapsfull',kind:'gapsfull',title:'Dein Lückentext',skill:'Grundlagen',question:'Ergänze die fünf Lücken in genau den drei Sätzen deiner Vorlage.',fields:[cwText('cwParallel','Verlauf der Breitenkreise',['parallel']),cwText('cwReference','Bezugslinie',['Äquator','Aequator']),cwText('cwNorth','Vom …',['Nordpol']),cwText('cwSouth','Zum …',['Südpol','Suedpol']),cwText('cwLargest','Größter Breitenkreis',['Äquator','Aequator'])]},
{id:'house',kind:'house',title:'Draufsicht und Seitenansicht',skill:'Ansichten',question:'Dasselbe Haus und die Erdkugel aus zwei Blickrichtungen: Benenne die Ansichten und die Formen der Breitenkreise. Begründe eine Hausansicht in einem Satz.',fields:[cwText('houseA','Haus A: Ansicht',['Seitenansicht','Vorderansicht','Ansicht von vorn','von vorn','von vorne']),cwText('houseB','Haus B: Ansicht',['Draufsicht','Ansicht von oben','von oben','Vogelperspektive']),cwText('globeC','Modell C: Blickrichtung',['Draufsicht','Draufsicht auf den Nordpol','Blick auf den Nordpol','Polansicht']),cwText('globeD','Modell D: Blickrichtung',['Seitenansicht','Seitenansicht vom Äquator','Blick vom Äquator']),cwText('globeCShape','Modell C: Form der Breitenkreise',['Ringe','Ring','Kreise','Kreis','konzentrische Kreise']),cwText('globeDShape','Modell D: Form der Breitenkreise',['waagerechte Linien','Linien','waagerecht','parallele Linien'])]},
{id:'drawglobe',kind:'draw',title:'Linien auf der Erdkugel einzeichnen',skill:'Zeichnen',question:'Die Kreise zeigen die Erde von der Seite: Nordpol oben, Südpol unten. a) Äquator und weitere Breitenkreise; b) Nullmeridian und weitere Meridiane; c) beide Linienarten zusammen, einen Schnittpunkt markieren und die Linien benennen.',boards:['gLat','gLon','gBoth'],fields:[]},
{id:'spherequarters',kind:'spherequarters',title:'Die vier Viertelkugeln',skill:'Erdviertel',question:'Benenne die nummerierten Bereiche an der Kugel. Norden ist oben, Westen links, Osten rechts. Jedes Erdviertel setzt sich auf der Rückseite fort.',fields:cwQuarters('sphere')}
];
function cleanClasswork(d){const out={version:1,answers:{},point:null,drawings:{},descriptions:{},manual:{},index:0,started:false,submitted:false,color:BLUE};if(!d||d.version!==1)return out;
 const ids=new Set(cwTasks.flatMap(q=>(q.fields||[]).map(f=>f.id)).concat('reason'));
 for(const [k,v] of Object.entries(d.answers||{}))if(ids.has(k)&&typeof v==='string')out.answers[k]=v.slice(0,1000);
 if(d.point&&Number.isFinite(d.point.lat)&&Number.isFinite(d.point.lon)&&Math.abs(d.point.lat)<=90&&Math.abs(d.point.lon)<=180)out.point={lat:d.point.lat,lon:d.point.lon};
 for(const id of Object.keys(cwBoards)){out.drawings[id]=Array.isArray(d.drawings?.[id])?d.drawings[id].slice(0,80).filter(p=>p&&[BLUE,PINK].includes(p.color)&&Array.isArray(p.points)&&p.points.length>0&&p.points.length<=400&&p.points.every(x=>Array.isArray(x)&&x.length===2&&x.every((n,i)=>Number.isFinite(n)&&n>=0&&n<=(i?300:480)))):[];if(typeof d.descriptions?.[id]==='string')out.descriptions[id]=d.descriptions[id].slice(0,1000);}
 for(const id of Object.values(cwRubrics).flat().map(x=>x[0]))if([true,false].includes(d.manual?.[id]))out.manual[id]=d.manual[id];
 out.index=Math.max(0,Math.min(17,Math.floor(Number(d.index)||0)));out.started=d.started===true||d.submitted===true;out.submitted=d.submitted===true;out.color=[BLUE,PINK].includes(d.color)?d.color:BLUE;return out;
}
let cw=cleanClasswork(null),cwStorage=true,cwFinishConfirm=false,cwResetConfirm=false,cwInk=null;
try{cw=cleanClasswork(JSON.parse(localStorage.getItem(CW_STORE)||'null'));}catch{cwStorage=false;}
function cwSave(){try{localStorage.setItem(CW_STORE,JSON.stringify(cw));cwStorage=true;}catch{cwStorage=false;}const el=document.getElementById('cwSave');if(el)el.textContent=cwStorage?'Auf diesem Gerät gespeichert. Du kannst später hier fortsetzen.':'Speichern ist in diesem Browser nicht möglich. Lass die Seite geöffnet.';const progress=document.getElementById('cwProgress');if(progress)progress.textContent=cwTasks.filter(cwComplete).length+' von 18 Aufgaben bearbeitet';for(const [i,q] of cwTasks.entries()){const b=ROOT.querySelector?.(`.aw-exam-numbers [data-aw="cwGo:${i}"]`);if(b){b.textContent=(i+1)+(cwComplete(q)?' ✓':'');b.setAttribute('aria-label','PDF-Aufgabe '+(i+1)+(cwComplete(q)?', bearbeitet':''));}}}
function cwHasBoard(id){return !!cw.drawings[id]?.length||!!cw.descriptions[id]?.trim();}
function cwComplete(q){return q.kind==='map'?!!cw.point:q.kind==='draw'?q.boards.every(cwHasBoard):q.fields.every(f=>String(cw.answers[f.id]||'').trim());}
function gradeClasswork(answers,point){return cwTasks.map((q,index)=>{if(index<10)return gradeExam(answers,point)[index];const parts=q.fields.map(f=>{const raw=String(answers[f.id]||'').trim(),v=f.kind==='number'?number(raw,f.max):null,ok=f.kind==='number'?v!==null&&v===f.target:f.answers.some(a=>normalWord(a)===normalWord(raw));return {id:f.id,label:f.label,points:ok?f.points:0,max:f.points,answered:raw!=='',expected:f.kind==='number'?String(f.target):f.answers[0]};});return {id:q.id,skill:q.skill,parts,points:parts.reduce((n,p)=>n+p.points,0),max:parts.reduce((n,p)=>n+p.max,0),answered:parts.some(p=>p.answered),ok:parts.length>0&&parts.every(p=>p.points===p.max),text:({halflabels:'Nord/Süd trennt der Äquator; Ost/West begrenzen Nullmeridian und 180°-Meridian.',cross:'Oben: Nordwest und Nordost. Unten: Südwest und Südost.',polelabels:'Die Breite reicht von 0° am Äquator bis 90° an den Polen.',gapsfull:window.AW_DATA.notes.sentences.join(' '),house:'An der Seite siehst du die Hauswand. Von oben siehst du das Dach. Vom Pol erscheinen Breitenkreise als Ringe; vom Äquator als waagerechte Linien.',spherequarters:'1 Nordwestviertel, 2 Nordostviertel, 3 Südwestviertel, 4 Südostviertel.'})[q.id]||'',code:'answer'};});}
function cwField(f){return `<div class="aw-exam-field"><label for="cw-${f.id}">${E(f.label)} <small>(${scoreText(f.points)} P.)</small></label>${f.options?`<select id="cw-${f.id}" data-cw-answer="${f.id}" ${cw.submitted?'disabled':''}><option value="">Bitte wählen</option>${f.options.map(([v,t])=>`<option value="${E(v)}" ${cw.answers[f.id]===v?'selected':''}>${E(t)}</option>`).join('')}</select>`:`<input id="cw-${f.id}" data-cw-answer="${f.id}" type="text" ${f.kind==='number'?'inputmode="decimal"':''} autocomplete="off" maxlength="120" value="${E(cw.answers[f.id]||'')}" ${cw.submitted?'disabled':''}>`}</div>`;}
function cwInline(id){return `<input id="cw-${id}" aria-label="${E(cwTasks[14].fields.find(f=>f.id===id).label)}" data-cw-answer="${id}" value="${E(cw.answers[id]||'')}" maxlength="80" ${cw.submitted?'disabled':''}>`;}
function cwDrawBoard(id){const [title]=cwBoards[id];return `<div class="aw-sketch-board"><h3>${title}</h3><svg viewBox="0 0 480 300" data-cw-draw="${id}" role="img" aria-label="Zeichenfläche: ${title}" style="touch-action:${cw.submitted?'auto':'none'}"><circle cx="240" cy="150" r="110" fill="#fff" stroke="#19384d" stroke-width="1.5"/>${id.startsWith('g')?'<text x="240" y="25" text-anchor="middle" fill="#19384d">Nordpol</text><text x="240" y="287" text-anchor="middle" fill="#19384d">Südpol</text>':''}<g data-cw-ink>${(cw.drawings[id]||[]).map(inkPath).join('')}</g></svg>${cw.submitted?'':`<div class="aw-controls">${button('Letzten Strich zurücknehmen','cwUndo:'+id,cw.drawings[id]?.length?'':'disabled')}</div>`}<label for="cw-description-${id}">Beschriftung oder Lösung mit der Tastatur beschreiben</label><textarea id="cw-description-${id}" data-cw-description="${id}" rows="2" maxlength="1000" ${cw.submitted?'disabled':''}>${E(cw.descriptions[id]||'')}</textarea></div>`;}
function cwHouseGraphic(){return `<div class="aw-grid2"><figure><figcaption>Haus A</figcaption><svg viewBox="0 0 260 200" role="img" aria-label="Haus A"><rect x="68" y="84" width="124" height="90" fill="#f1d8a9" stroke="#19384d"/><rect x="155" y="49" width="16" height="44" fill="#d5d7da" stroke="#19384d"/><path d="M54 84L130 32L206 84Z" fill="#ba6a52" stroke="#19384d"/><path d="M116 174V127H144V174" fill="#d4b281" stroke="#19384d"/><path d="M79 109H101V132H79ZM160 109H182V132H160Z" fill="#ddeff5" stroke="#19384d"/></svg></figure><figure><figcaption>Haus B</figcaption><svg viewBox="0 0 260 200" role="img" aria-label="Haus B"><path d="M62 44H198V161H62Z" fill="#c97a5c" stroke="#19384d"/><path d="M130 44V161" stroke="#19384d" stroke-width="2"/><path d="M157 60H175V79H157Z" fill="#d5d7da" stroke="#19384d"/></svg></figure><figure><figcaption>Modell C</figcaption>${examModelGraphic('parallel-pole','Modell C')}</figure><figure><figcaption>Modell D</figcaption>${examModelGraphic('parallel-side','Modell D')}</figure></div>`;}
function cwSphereGraphic(solved=false){const labels=solved?['Nordwestviertel','Nordostviertel','Südwestviertel','Südostviertel']:['1','2','3','4'];return '<div class="cw-sphere">'+svg('Kugelzeichnung: Nordpol oben, Äquator waagerecht, Nullmeridian in der Mitte',`<defs><clipPath id="cwSphereClip"><circle cx="270" cy="205" r="150"/></clipPath></defs><g clip-path="url(#cwSphereClip)"><path d="M120 55H270V205H120Z" fill="#e4eef9"/><path d="M270 55H420V205H270Z" fill="#e7f3e7"/><path d="M120 205H270V355H120Z" fill="#f7ead9"/><path d="M270 205H420V355H270Z" fill="#f2e4f1"/><ellipse cx="270" cy="205" rx="75" ry="150" fill="none" stroke="#9db4c5"/><path d="M120 130H420M120 280H420" stroke="#9db4c5"/></g><circle cx="270" cy="205" r="150" fill="none" stroke="#19384d"/><path d="M120 205H420" stroke="${BLUE}" stroke-width="3"/><path d="M270 55V355" stroke="${PINK}" stroke-width="3"/><g fill="#19384d" text-anchor="middle" font-size="${solved?15:25}" font-weight="bold">${labels.map((t,i)=>`<text x="${i%2?337:203}" y="${i<2?143:285}">${t}</text>`).join('')}<text x="270" y="32" font-size="16">Nordpol</text><text x="270" y="382" font-size="16">Südpol</text></g><text x="430" y="210" fill="${BLUE}" font-size="15">Äquator</text><text x="285" y="80" fill="${PINK}" font-size="16">0°</text>`,'0 0 560 410')+'</div>';}
function cwManualReview(q){const criteria=cwRubrics[q.id];if(!criteria)return '';return `<section class="aw-callout"><h3>Gemeinsam bewerten: ${criteria.length} ${criteria.length===1?'Punkt':'Punkte'}</h3><p>Prüfe Zeichnung und Beschriftung mit der Musterlösung. Diese Punkte werden von einer Lehrkraft oder gemeinsam eingetragen; die App erkennt Freihandzeichnungen nicht automatisch.</p>${criteria.map(([id,t])=>`<div class="cw-rubric"><label for="cw-manual-${id}">${E(t)} · 1 Punkt</label><select id="cw-manual-${id}" data-cw-manual="${id}"><option value="" ${!(id in cw.manual)?'selected':''}>Noch nicht bewertet</option><option value="1" ${cw.manual[id]===true?'selected':''}>Erfüllt · 1 Punkt</option><option value="0" ${cw.manual[id]===false?'selected':''}>Noch nicht erfüllt · 0 Punkte</option></select></div>`).join('')}</section>`;}
function cwSolution(q){if(q.id==='viewsdraw')return originalScene('views');if(q.id==='drawglobe')return originalScene('globe');if(q.id==='spherequarters')return cwSphereGraphic(true);if(q.id==='halflabels')return originalScene('hemispheres');if(q.id==='polelabels')return originalScene('angle');if(q.id==='house')return '<p>Haus A: Seitenansicht, zum Beispiel an der Hauswand mit Tür und Fenstern erkennbar. Haus B: Draufsicht auf das Dach.</p>';return '';}
function cwQuestion(q){let art='';if(q.kind==='views')art=`<div class="aw-grid2">${q.models.map((kind,i)=>`<figure><figcaption>Modell ${i?'B':'A'}</figcaption>${examModelGraphic(kind,'Modell '+(i?'B':'A'))}</figure>`).join('')}</div>`;
 if(q.kind==='map')art=mapControls()+flatMap(q.map,{pick:cw.submitted?null:'cw',marker:cw.point,city:q.target,point:cw.submitted}).replace('data-aw-pick="cw"','data-cw-map="true"')+(cw.submitted?'<p>Gelber Punkt: Lösung. Kreuz: dein Punkt.</p>':`<div class="aw-controls">${[['N','↑ Norden'],['W','← Westen'],['O','→ Osten'],['S','↓ Süden']].map(([d,t])=>button(t,'cwMove:'+d)).join('')}</div><p role="status">Dein Punkt: ${pickedText(cw.point)}</p>`);
 if(q.kind==='readpoint')art=mapControls()+flatMap(q.map,{marker:q.target});if(q.kind==='register')art=examRegisterTable();if(q.kind==='longitude')art=mapControls()+flatMap(q.map,{names:true,onlyCity:q.city});
 if(q.kind==='labels')art=originalScene('hemispheresTest');if(q.kind==='cross')art=originalScene('quartersTest');if(q.kind==='polelabels')art=originalScene('angleTest');if(q.kind==='house')art=cwHouseGraphic();if(q.kind==='spherequarters')art=cwSphereGraphic()+`<p class="aw-muted">Vereinfachte Vorderansicht. Die zweite Ost-/Westgrenze liegt am 180°-Meridian auf der Rückseite.</p>`;
 if(q.kind==='draw')art=(cw.submitted?'':`<p>Mit Maus, Finger oder Stift zeichnen. Alternativ beschreiben: Die Form der Linien wird dann gemeinsam besprochen.</p><div class="aw-controls">${button('Blauer Stift','cwColor:blue',`aria-pressed="${cw.color===BLUE}"`)}${button('Violetter Stift','cwColor:purple',`aria-pressed="${cw.color===PINK}"`)}</div>`)+`<div class="aw-sketch-four">${q.boards.map(cwDrawBoard).join('')}</div>`;
 const auto=q.fields?.reduce((n,f)=>n+f.points,0)||(q.kind==='map'?2:0),manual=cwRubrics[q.id]?.length||0;
 let fields=q.kind==='gapsfull'?`<div class="aw-original-gaps"><p>Die Breitenkreise verlaufen ${cwInline('cwParallel')} zum ${cwInline('cwReference')}.</p><p>Die Längenkreise verlaufen vom ${cwInline('cwNorth')} zum ${cwInline('cwSouth')}.</p><p>Der größte Breitenkreis ist der ${cwInline('cwLargest')}.</p></div>`:`<div class="aw-grid2 aw-exam-fields">${(q.fields||[]).map(cwField).join('')}</div>`;
 const result=cw.submitted?gradeClasswork(cw.answers,cw.point).find(r=>r.id===q.id):null;
 return `<section class="aw-card cw-question" id="cwQuestion" tabindex="-1"><span class="aw-kicker">Aufgabe ${cw.index+1} / 18 · PDF-Aufgabe ${cw.index+1} · ${auto?scoreText(auto)+' Punkte automatisch prüfbar':''}${manual?(auto?' + ':'')+manual+' Punkte gemeinsam bewerten':''}</span><h2>${cw.index+1}. ${E(q.title)}</h2><p class="aw-exam-instruction">${E(q.question)}</p>${art}${fields}${q.id==='house'?`<label for="cw-reason">Begründe eine Hausansicht in einem Satz.</label><textarea id="cw-reason" data-cw-answer="reason" maxlength="1000" rows="3" ${cw.submitted?'disabled':''}>${E(cw.answers.reason||'')}</textarea>`:''}${result&&result.max?examQuestionResult(result):''}${cw.submitted?`<details open><summary>Musterlösung und Bewertung</summary>${cwSolution(q)}${cwManualReview(q)}</details>`:''}</section>`;
}
function cwResult(){const r=gradeClasswork(cw.answers,cw.point),a=r.slice(0,10).reduce((n,q)=>n+q.points,0),b=r.slice(10).reduce((n,q)=>n+q.points,0),manual=Object.values(cwRubrics).flat(),checked=manual.filter(([id])=>cw.manual[id]).length;return `<section class="aw-card" id="cwResult" tabindex="-1"><h2>Deine Auswertung</h2><p><b>Teil A: ${scoreText(a)} / 20 Punkte.</b> Grundlagen, Ansichten, Karten- und Atlasarbeit wie in den PDF-Aufgaben 1–10.</p><p><b>Beschriftungen und Zuordnungen aus Teil B: ${scoreText(b)} / 34 Punkte.</b></p><p id="cwManualTotal"><b>Zeichnungen und Begründung: ${checked} ${checked===1?'Punkt':'Punkte'} gemeinsam eingetragen; ${Object.keys(cw.manual).length} von 11 Kriterien bewertet.</b> Noch nicht bewertete Kriterien bleiben offen.</p><p>Die Rückmeldung ist eine Lernhilfe und vergibt keine Schulnote. Deine abgegebenen Antworten bleiben unverändert.</p><div class="aw-controls">${cwTasks.map((q,i)=>button('Aufgabe '+(i+1)+' ansehen','cwGo:'+i)).join('')}</div><div class="aw-controls">${button('Beschriftungen und Gradnetz weiterüben','view:notes')}${button('Kartenarbeit weiterüben','view:mark')}${pdfLinks(true)}</div></section>`;}
function classworkView(){const answered=cwTasks.filter(cwComplete).length;const header=`<section class="aw-card"><span class="aw-kicker">NEU · 27.10.2026 · alle 18 Aufgaben der PDF</span><h2>Interaktive Klassenarbeit: Gradnetz, Ansichten und Atlas</h2><p>Erst selbst bearbeiten, dann abgeben. Du kannst in beliebiger Reihenfolge arbeiten, pausieren und zurückblättern. Lösungen erscheinen nach der Abgabe. 54 Teilpunkte sind automatisch prüfbar, 11 Punkte für Zeichnungen und eine Begründung werden gemeinsam bewertet.</p><p id="cwSave" role="status">${cwStorage?'Auf diesem Gerät gespeichert. Du kannst später hier fortsetzen.':'Speichern ist in diesem Browser nicht möglich. Lass die Seite geöffnet.'}</p><div class="aw-controls">${cw.started?button('Neuen Versuch beginnen','cwReset'):button('Klassenarbeit mit 18 Aufgaben starten','cwStart','class="aw-primary"')}${pdfLinks(cw.submitted)}</div>${cwResetConfirm?`<div class="aw-callout">Vorhandene Antworten und Zeichnungen für einen neuen Versuch leeren?<div class="aw-controls">${button('Neuen leeren Versuch starten','cwConfirmReset')}${button('Bisherigen Versuch behalten','cwKeep')}</div></div>`:''}</section>`;
 if(!cw.started)return header+`<section class="aw-card"><h3>Das kommt dran</h3><ol><li>Wissen, Koordinaten und Atlas (PDF 1–10)</li><li>Halbkugeln, Pole und Erdviertel beschriften (11–12)</li><li>Vier Ansichten selbst zeichnen, Halbkuppel und Lückentext (13–15)</li><li>Draufsicht und Seitenansicht, Gradnetz und Viertelkugeln (16–18)</li></ol><p>Zeichenflächen haben eine Tastaturalternative. Die Bewertungskriterien werden nach der Abgabe gemeinsam durchgegangen.</p></section>`;
 const missing=cwTasks.map((q,i)=>cwComplete(q)?null:i+1).filter(Boolean);
 return header+`<section class="aw-card"><p id="cwProgress" role="status">${answered} von 18 Aufgaben bearbeitet</p><nav class="aw-exam-numbers" aria-label="Aufgaben der vollständigen Klassenarbeit">${cwTasks.map((q,i)=>button(`${i+1}${cwComplete(q)?' ✓':''}`,'cwGo:'+i,`aria-label="PDF-Aufgabe ${i+1}${cwComplete(q)?', bearbeitet':''}" aria-current="${i===cw.index?'step':'false'}"`)).join('')}</nav></section>${cwQuestion(cwTasks[cw.index])}<section class="aw-card"><div class="aw-controls">${button('← Vorherige Aufgabe','cwGo:'+Math.max(0,cw.index-1),cw.index===0?'disabled':'')}${cw.index<17?button('Nächste Aufgabe →','cwGo:'+(cw.index+1),'class="aw-primary"'):''}${cw.submitted?button('Auswertung ansehen','cwResults'):button('Klassenarbeit abgeben','cwFinish','class="aw-primary"')}</div>${cwFinishConfirm?`<div class="aw-callout" role="status"><h3>Abgabe prüfen</h3><p>${missing.length?'Noch nicht vollständig bearbeitet: Aufgaben '+missing.join(', ')+'.':'Alle Aufgaben sind bearbeitet.'} Nach der Abgabe bleiben die Antworten unverändert.</p><div class="aw-controls">${button('Jetzt endgültig abgeben','cwSubmit')}${button('Weiterbearbeiten','cwCancelFinish')}</div></div>`:''}</section>${cw.submitted?cwResult():''}`;
}
function cwCommand(action,value){if(action==='cwStart'){cw.started=true;cwSave();renderHere();return;}if(action==='cwReset'){cwResetConfirm=true;renderHere();return;}if(action==='cwKeep'){cwResetConfirm=false;renderHere();return;}if(action==='cwConfirmReset'){cw=cleanClasswork(null);cw.started=true;cwResetConfirm=false;cwFinishConfirm=false;cwSave();renderHere();return;}if(action==='cwGo'){cw.index=Math.max(0,Math.min(17,Number(value)||0));cwFinishConfirm=false;cwSave();renderHere();document.getElementById('cwQuestion')?.focus();return;}if(action==='cwFinish'){cwFinishConfirm=true;renderHere();return;}if(action==='cwCancelFinish'){cwFinishConfirm=false;renderHere();return;}if(action==='cwSubmit'){if(cw.submitted)return;cw.submitted=true;cwFinishConfirm=false;cwSave();renderHere();document.getElementById('cwResult')?.focus();return;}if(action==='cwResults'){document.getElementById('cwResult')?.focus();return;}if(cw.submitted)return;if(action==='cwColor'){cw.color=value==='purple'?PINK:BLUE;cwSave();renderHere();return;}if(action==='cwUndo'){cw.drawings[value]?.pop();cwSave();renderHere();return;}if(action==='cwMove'){const m=maps.germany,[w,e,so,n]=m.bounds,p=cw.point||{lat:(so+n)/2,lon:(w+e)/2};cw.point={lat:round(Math.max(so,Math.min(n,p.lat+(value==='N'?1:value==='S'?-1:0)))),lon:round(Math.max(w,Math.min(e,p.lon+(value==='O'?1:value==='W'?-1:0))))};cwSave();renderHere();}}
ROOT.addEventListener('input',e=>{if(cw.submitted)return;const id=e.target.dataset.cwAnswer,desc=e.target.dataset.cwDescription;if(id)cw.answers[id]=e.target.value;if(desc)cw.descriptions[desc]=e.target.value;if(id||desc)cwSave();});
ROOT.addEventListener('change',e=>{const id=e.target.dataset.cwManual;if(id&&cw.submitted){if(e.target.value==='')delete cw.manual[id];else cw.manual[id]=e.target.value==='1';cwSave();const el=document.getElementById('cwManualTotal');if(el)el.innerHTML='<b>Zeichnungen und Begründung: '+Object.values(cw.manual).filter(Boolean).length+' '+(Object.values(cw.manual).filter(Boolean).length===1?'Punkt':'Punkte')+' gemeinsam eingetragen; '+Object.keys(cw.manual).length+' von 11 Kriterien bewertet.</b> Noch nicht bewertete Kriterien bleiben offen.';return;}if(!cw.submitted&&e.target.dataset.cwAnswer){cw.answers[e.target.dataset.cwAnswer]=e.target.value;cwSave();}});
ROOT.addEventListener('click',e=>{const art=e.target.closest('svg[data-cw-map]');if(!art||cw.submitted)return;const matrix=art.getScreenCTM();if(!matrix)return;const pt=art.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const local=pt.matrixTransform(matrix.inverse()),p=pointFromMap(local.x,local.y,art.dataset.awMapKey);if(p){cw.point=p;cwSave();renderHere();}});
ROOT.addEventListener('keydown',e=>{const region=e.target.closest('.aw-map-scroll'),art=region?.querySelector('svg[data-cw-map]'),d={ArrowUp:'N',ArrowDown:'S',ArrowLeft:'W',ArrowRight:'O'}[e.key];if(art&&d&&!cw.submitted){e.preventDefault();cwCommand('cwMove',d);ROOT.querySelector('svg[data-cw-map]')?.closest('.aw-map-scroll')?.focus();}});
ROOT.addEventListener('pointerdown',e=>{const art=e.target.closest('svg[data-cw-draw]');if(!art||cw.submitted||e.button>0)return;const id=art.dataset.cwDraw;if((cw.drawings[id]||[]).length>=80)return;e.preventDefault();art.setPointerCapture(e.pointerId);const path={color:cw.color,points:[sketchXY(e,art)]};(cw.drawings[id]??=[]).push(path);cwInk={art,path,pointer:e.pointerId,id};art.querySelector('[data-cw-ink]').insertAdjacentHTML('beforeend',inkPath(path));});
ROOT.addEventListener('pointermove',e=>{if(!cwInk||cwInk.pointer!==e.pointerId||cwInk.path.points.length>=400)return;e.preventDefault();const p=sketchXY(e,cwInk.art),last=cwInk.path.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])<1)return;cwInk.path.points.push(p);cwInk.art.querySelector('[data-cw-ink]').lastElementChild.setAttribute('d',cwInk.path.points.map((xy,i)=>(i?'L':'M')+xy.join(',')).join(' '));});
function cwEndInk(e){if(!cwInk||cwInk.pointer!==e.pointerId)return;const id=cwInk.id;cwInk=null;cwSave();const b=ROOT.querySelector(`[data-aw="cwUndo:${id}"]`);if(b)b.disabled=false;}
ROOT.addEventListener('pointerup',cwEndInk);ROOT.addEventListener('pointercancel',cwEndInk);

function sources(){return `<details class="aw-sources"><summary>Fachliche Grundlagen und Kartenquellen</summary><p>Eigene Lernmodelle nach den eingereichten Unterrichtsskizzen. Keine kopierten Atlaskarten. Vereinfachte Küstenkonturen: Natural Earth, Public Domain.</p><ul><li><a href="https://oceanservice.noaa.gov/education/tutorial_nautical_charts/nautical_charts02_information_2b.html" target="_blank" rel="noopener">NOAA: geografische Breite und Länge</a></li><li><a href="https://oceanservice.noaa.gov/facts/longitude.html" target="_blank" rel="noopener">NOAA: Nullmeridian, 180°-Meridian und Datumsgrenze</a></li>${cityData.map(p=>`<li><a href="${p.source}" target="_blank" rel="noopener">Ortslage ${p.name}: ${coord(p.lat,p.lon)}, auf 0,1° gerundet</a></li>`).join('')}</ul><p>GeoNames-Ortslagen: CC BY 4.0. Alice Springs: Place Names Register, Northern Territory Government. Fach- und Datenprüfung: 26.10.2026. Alle Übungen funktionieren ohne diese externen Links.</p></details>`;}
function show(){
 const views={notes:notesView,globe:globeView,quarters:quartersView,views:viewsView,mark:markView,atlas:atlasView,register:registerView,gaps:gapView,exam:examView,sketch:sketchView,classwork:classworkView};
 const group=['notes','globe','quarters','views'].includes(s.view)?'learn':['mark','gaps'].includes(s.view)?'practice':['atlas','register'].includes(s.view)?'atlas':'exam';
 const sub=group==='learn'?[['notes','Deine Unterrichtsskizzen'],['globe','Gradnetz und Globus'],['quarters','Erdviertel'],['views','Polansichten']]:group==='practice'?[['mark','Orte selbst markieren'],['gaps','Lückentext']]:group==='atlas'?[['atlas','Ortssuche'],['register','Registerwerkstatt']]:[];
 return `<div class="aw"><header class="aw-hero aw-hero-compact"><span class="aw-kicker">Gustavs Gradnetz- und Atlaswerkstatt</span><h1>Verstehen. Selbst finden. Sicher anwenden.</h1><p>Gehe deinen Lernweg in vier Schritten. Übe zunächst selbst. Hilfen und Musterlösungen öffnest du gezielt.</p><div class="aw-chips"><span class="aw-lat">━ Breite · N / S</span><span class="aw-lon">┃ Länge · O / W</span><span>20 Orte · alle Erdviertel</span></div><div class="aw-progress"><span class="aw-complete">${s.done.size} unterschiedliche Übungsaufgaben gelöst</span>${button('Lernfortschritt zurücksetzen','askReset','class="aw-small"')}</div></header><nav class="aw-nav aw-learning-path" aria-label="Dein Lernweg">${[['learn','notes','1 · Verstehen'],['practice','mark','2 · Selbst üben'],['atlas','atlas','3 · Atlas benutzen'],['exam','classwork','4 · Klassenarbeit']].map(([g,v,t])=>button(t,'view:'+v,`aria-current="${g===group?'page':'false'}"`)).join('')}</nav>${sub.length?`<nav class="aw-controls aw-secondary" aria-label="Themen in diesem Lernschritt">${sub.map(([v,t])=>button(t,'view:'+v,`aria-pressed="${s.view===v}"`)).join('')}</nav>`:''}<div id="awSection">${(views[s.view]||globeView)()}</div><details><summary>Mein Übungsstand nach Bereichen</summary><div class="aw-table-scroll"><table class="aw-register-table"><thead><tr><th>Bereich</th><th>Geprüfte Antworten</th><th>Davon passend</th><th>Versuche mit Hilfe</th></tr></thead><tbody>${Object.entries(s.stats).map(([k,v])=>`<tr><td>${k}</td><td>${v.attempts}</td><td>${v.correct}</td><td>${v.assisted}</td></tr>`).join('')}</tbody></table></div><p class="aw-muted">Wiederholungen zählen als weitere Versuche. Angezeigte Lösungen werden nicht als selbstständig gelöste Aufgaben gewertet. Die Übersicht ist ein Lernhinweis.</p></details>${sources()}</div>`;
}
function updateGlobe(){
 const g=document.getElementById('awGlobe');if(!g)return;g.innerHTML=globeGraphic();
 document.getElementById('awAngle').innerHTML=angleGraphic();
 document.getElementById('awLatOut').textContent=latText(s.lat);document.getElementById('awLonOut').textContent=lonText(s.lon);
 document.getElementById('awPoint').innerHTML=pointSummary();
}
function renderHere(){render();}
function spin(now){if(!s.spin||state.tab!=='atlaswerkstatt'||s.view!=='globe')return;
 if(last){s.camLon=((s.camLon+Math.min(now-last,100)*.012+180)%360)-180;updateGlobe();document.getElementById('awCamera').value=s.camLon;}
 last=now;raf=requestAnimationFrame(spin);
}
function playStep(){if(!s.playing||state.tab!=='atlaswerkstatt')return;
 timer=setTimeout(()=>{if(document.hidden){stop();renderHere();return;}s.step++;if(s.step>=4){s.step=4;s.playing=false;}renderHere();if(s.playing)playStep();},2200);
}
function answer(){const p=cityData[s.city];
 if(s.mode==='coords'){
  const input=normalWord(s.answer),ok=p.aliases.some(x=>normalWord(x)===input),wrong=cityData.find(x=>x.aliases.some(a=>normalWord(a)===input));
  let message=ok?`Richtig: ${p.name}, ${p.country}. Die Ortslage passt zu ${coord(p.lat,p.lon)}.`:!input?'Trage zuerst einen Ortsnamen ein.':'Prüfe beide Gradangaben und suche auf der passenden Regionalkarte den Schnittpunkt.';
  if(input==='frankfurt')message='Der Name Frankfurt ist mehrdeutig. Prüfe die Region und nenne Frankfurt am Main oder Frankfurt (Oder).';
  else if(!ok&&wrong){const q1=quarter(wrong.lat,wrong.lon),q2=quarter(p.lat,p.lon);message=q1.code!==q2.code?`Deine genannte Stadt liegt im ${q1.name}. Kontrolliere zuerst N/S und O/W der Aufgabe.`:'Du hast einen anderen Ort in diesem Erdviertel genannt. Vergleiche nun die genauen Zahlen von Breite und Länge.';}
  s.feedback={ok,text:message};
 }else s.feedback=checkMissing(s.answer,s.direction,s.mode==='nameLat'?p.lon:p.lat,s.mode==='nameLon',s.mode==='nameLat'?p.lat:p.lon);
 const helped=s.demonstrate||s.hintLevel>0;note('Atlasarbeit',s.feedback.ok,helped);
 if(s.feedback.ok&&!s.demonstrate&&s.hintLevel<5)mark(s.mode+':'+p.id);renderHere();
}
function command(cmd){const [action,value]=cmd.split(':');
 if(action.startsWith('cw')){cwCommand(action,value);return;}
 if(action==='sketchColor'){sketch.color=value==='purple'?PINK:BLUE;saveSketch();renderHere();return;}
 if(action==='sketchUndo'){sketch.paths[value]?.pop();saveSketch();renderHere();return;}
 if(action==='sketchReview'){sketch.review=true;saveSketch();renderHere();return;}
 if(action==='mapZoom'){s.mapZoom=value==='0'?1:Math.min(3,Math.max(1,s.mapZoom+Number(value)*.5));renderHere();return;}
 if(action==='globeZoom'){s.globeZoom=value==='0'?1:Math.min(3,Math.max(1,s.globeZoom+Number(value)*.5));renderHere();return;}
 if(action==='markCheck'){const p=cityData[s.markIndex],[w,e,so,n]=maps[s.markMap].bounds,wrongMap=p.lon<w||p.lon>e||p.lat<so||p.lat>n;s.markFeedback=wrongMap?{ok:false,code:'map',text:'Die gesuchte Lage liegt außerhalb der Randwerte dieser Karte. Wähle zuerst die Weltkarte oder eine passende Regionalkarte.'}:s.markPoint?coordinateFeedback(s.markPoint.lat,s.markPoint.lon,p,s.markMap==='world'?3:1):{ok:false,text:'Tippe zuerst einen Punkt in die Karte oder bewege ihn mit den Richtungstasten.'};if(s.markPoint){note('Kartenarbeit',s.markFeedback.ok,!!s.markSolution);if(s.markFeedback.ok&&!s.markSolution)mark('punkt:'+p.id);}renderHere();return;}
 if(action==='markNext'){s.markIndex=(s.markIndex+1)%cityData.length;s.markMap=cityData[s.markIndex].map;s.markPoint=null;s.markFeedback=null;s.markSolution=false;renderHere();return;}
 if(action==='markSolution'){s.markSolution=true;renderHere();return;}
 if(action==='markMove'||action==='examMove'){const type=action==='markMove'?'mark':'exam';if(type==='exam'&&s.examSubmitted)return;const key=type==='mark'?s.markMap:window.AW_DATA.exam.find(q=>q.kind==='map').map,[w,e,so,n]=maps[key].bounds,prop=type==='mark'?'markPoint':'examPoint',p=s[prop]||{lat:(so+n)/2,lon:(w+e)/2},delta=type==='exam'?1:maps[key].step/5;s[prop]={lat:round(Math.min(n,Math.max(so,p.lat+(value==='N'?delta:value==='S'?-delta:0)))),lon:round(Math.min(e,Math.max(w,p.lon+(value==='O'?delta:value==='W'?-delta:0))))};if(type==='mark')s.markFeedback=null;else {s.examResult=null;saveExamDraft();}renderHere();return;}
 if(action==='hintNext'){s.hintLevel=Math.min(5,s.hintLevel+1);if(s.hintLevel>=2)s.atlasMap=cityData[s.city].map;renderHere();return;}
 if(action==='independent'){resetAtlas();renderHere();return;}
 if(action==='demonstrate'){stop();s.demonstrate=true;s.step=0;renderHere();return;}
 if(action==='registerNext'){s.registerIndex=(s.registerIndex+1)%registerCases.length;s.registerChoice='';s.registerMapChoice='';s.registerField='';s.registerSearch='';s.registerResult=null;renderHere();return;}
 if(action==='examNew'){if(s.examActive&&(Object.keys(s.examAnswers).length||s.examPoint||s.examSubmitted)){s.examResetConfirm=true;renderHere();}else beginNewExam();return;}
 if(action==='examConfirmReset'){beginNewExam();return;}
 if(action==='examKeep'){s.examResetConfirm=false;renderHere();return;}
 if(action==='examGo'){s.examIndex=Math.max(0,Math.min(9,Number(value)||0));saveExamDraft();renderHere();ROOT.querySelector('.aw-exam-question')?.scrollIntoView({block:'start'});return;}
 if(action==='examShowResult'){document.getElementById('awExamResults')?.focus();return;}

 if(action==='gapReset'){s.gaps={};s.gapFeedback=null;s.gapSolution=false;s.gapSeenSolution=false;s.gapHelpUsed=false;renderHere();return;}
 if(action==='gapSolution'){s.gapSolution=!s.gapSolution;s.gapSeenSolution=true;renderHere();return;}
 if(action==='view'){stop();s.view=value;renderHere();return;}
 if(action==='layer'){stop();s.layer=value;renderHere();return;}
 if(action==='camera'){stop();s.camLat=({equator:0,north:90,south:-90})[value];s.camLon=0;renderHere();return;}
 if(action==='focus'){stop();s.camLon=s.lon;s.camLat=s.lat;renderHere();return;}
 if(action==='spin'){
  if(reduced()){s.camLon=(s.camLon+20+180)%360-180;renderHere();return;}
  s.spin=!s.spin;const b=document.getElementById('awSpin');b.textContent=s.spin?'Drehung anhalten':'Drehung starten';b.setAttribute('aria-pressed',String(s.spin));if(s.spin){last=0;raf=requestAnimationFrame(spin);}else cancelAnimationFrame(raf);return;
 }
 if(action==='quarter'){const t=quarterTasks[s.quarterIndex],q=quarter(...t),ok=q.code===value;s.quarterFeedback={ok,text:ok?`${q.name}: ${q.detail}`:`Schau noch einmal: ${q.detail}`};note('Erdviertel',ok,s.quarterHelpUsed);if(ok)mark('viertel:'+s.quarterIndex);renderHere();return;}
 if(action==='quarterNext'){s.quarterIndex=(s.quarterIndex+1)%quarterTasks.length;s.quarterFeedback=null;s.quarterHelpUsed=false;renderHere();return;}
 if(action==='checkViews'){
  const missing=viewCases.filter(([id])=>!s.viewAnswers[id]);
  if(missing.length)s.viewFeedback=`<div class="aw-feedback" data-good="false">Wähle zuerst in allen vier Feldern eine Form aus.</div>`;
  else {let correct=0;s.viewFeedback=viewCases.map(([id,title,key])=>{const ok=s.viewAnswers[id]===key;note('Ansichten',ok,s.viewHelpUsed);if(ok){correct++;mark('ansicht:'+id);}return `<p><b>${E(title)}:</b> ${ok?'Das passt.':({waagerecht:'Breitenkreise erscheinen waagerecht.',ringe:'Vom Pol siehst du Ringe.',boegen:'Meridiane erscheinen als Bögen von Pol zu Pol.',strahlen:'Meridiane erscheinen wie Speichen zum Pol.'})[key]}</p>`;}).join('');s.viewFeedback=`<div class="aw-feedback" data-good="${correct===4}"><b>${correct} von 4 passen.</b>${s.viewFeedback}</div>`;}
  renderHere();return;
 }
 if(action==='step'){stop();s.demonstrate=true;s.step=+value;renderHere();return;}
 if(action==='play'){if(s.playing){stop();renderHere();return;}if(reduced()){s.step=Math.min(4,s.step+1);renderHere();return;}stop();s.step=0;s.playing=true;renderHere();playStep();return;}
 if(action==='mode'){s.mode=value;resetAtlas();renderHere();return;}
 if(action==='nextCity'){s.city=(s.city+1)%cityData.length;resetAtlas();renderHere();return;}
 if(action==='register'){stop();s.city=cityData.findIndex(p=>p.id===value);s.mode='nameLat';s.direction='O';s.step=1;s.answer='';s.feedback=null;renderHere();return;}
 if(action==='askReset'){
  const b=ROOT.querySelector('[data-aw="askReset"]');b.outerHTML='<span class="aw-row">Nur die neuen Werkstatt-Ergebnisse löschen? '+button('Ja, zurücksetzen','reset')+button('Behalten','keep')+'</span>';return;
 }
 if(action==='reset'){s.done.clear();for(const v of Object.values(s.stats)){v.attempts=0;v.correct=0;v.assisted=0;}persistWorkshop();renderHere();return;}
 if(action==='keep')renderHere();
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-aw]');if(!el)return;e.preventDefault();e.stopPropagation();if(el.dataset.aw==='openClasswork'){stop();state.tab='atlaswerkstatt';s.view='classwork';renderHere();return;}if(el.dataset.aw==='open'){stop();state.tab='atlaswerkstatt';state.view='home';renderHere();return;}command(el.dataset.aw);},true);
ROOT.addEventListener('submit',e=>{if(e.target.id==='awRegisterForm'){e.preventDefault();checkRegister();return;}if(e.target.id==='awExamForm'){e.preventDefault();finishExam();return;}if(e.target.id==='awGapForm'){e.preventDefault();s.gapFeedback=checkGaps(s.gaps);s.gapFeedback.forEach(r=>note('Grundlagen',r.ok,s.gapSeenSolution||s.gapHelpUsed));if(!s.gapSeenSolution)s.gapFeedback.filter(r=>r.ok).forEach(r=>mark('merksatz:'+r.id));renderHere();return;}if(e.target.id==='awAnswerForm'){e.preventDefault();answer();}});
ROOT.addEventListener('input',e=>{const el=e.target;if(el.dataset.awGap){s.gaps[el.dataset.awGap]=el.value;s.gapFeedback=null;const input=el;input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');const hint=document.getElementById('aw-gap-feedback-'+el.dataset.awGap);if(hint){hint.textContent='Erneut prüfen';hint.removeAttribute('data-good');}const total=ROOT.querySelector('.aw-feedback[role="status"]');if(total){total.textContent='Eintrag geändert. Prüfe deine Lücken erneut.';total.removeAttribute('data-good');}}if(el.dataset.awInput){if(s.spin){stop();const b=document.getElementById('awSpin');if(b){b.textContent=reduced()?'20° weiterdrehen':'Drehung starten';b.setAttribute('aria-pressed','false');}}s[el.dataset.awInput]=Number(el.value);updateGlobe();}if(el.hasAttribute('data-aw-answer')){s.answer=el.value;if(s.playing){stop();const b=document.getElementById('awPlay');if(b){b.textContent='Suchweg abspielen';b.setAttribute('aria-pressed','false');}}}});
ROOT.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-aw-example')){s.city=Number(el.value);resetAtlas();renderHere();}if(el.hasAttribute('data-aw-direction'))s.direction=el.value;if(el.dataset.awView)s.viewAnswers[el.dataset.awView]=el.value;});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&(s.spin||s.playing)){stop();if(state.tab==='atlaswerkstatt')renderHere();}});
ROOT.addEventListener('click',e=>{const art=e.target.closest('svg[data-aw-pick]');if(!art)return;const matrix=art.getScreenCTM();if(!matrix)return;const pt=art.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const q=pt.matrixTransform(matrix.inverse()),p=pointFromMap(q.x,q.y,art.dataset.awMapKey);if(!p)return;e.preventDefault();const type=art.dataset.awPick;if(type==='mark'){s.markPoint=p;s.markFeedback=null;}else {if(s.examSubmitted)return;s.examPoint=p;s.examResult=null;saveExamDraft();}renderHere();});
ROOT.addEventListener('keydown',e=>{const region=e.target.closest('.aw-map-scroll'),art=region?.querySelector('svg[data-aw-pick]'),dir={ArrowUp:'N',ArrowDown:'S',ArrowLeft:'W',ArrowRight:'O'}[e.key];if(art&&dir){e.preventDefault();const type=art.dataset.awPick;command(type+'Move:'+dir);ROOT.querySelector(`svg[data-aw-pick="${type}"]`)?.closest('.aw-map-scroll')?.focus();}});
ROOT.addEventListener('input',e=>{const el=e.target;
 if(el.hasAttribute('data-aw-register-search')){s.registerSearch=el.value;const body=document.getElementById('awRegisterRows');if(body)body.innerHTML=registerRows(s.registerSearch);}
 if(el.hasAttribute('data-aw-register-field')){s.registerField=el.value;s.registerResult=null;const result=document.getElementById('awRegisterResult');if(result){result.textContent='Suchfeld geändert. Bitte prüfe die Registersuche erneut.';result.removeAttribute('data-good');}}
 if(el.dataset.awExam){if(s.examSubmitted)return;s.examAnswers[el.dataset.awExam]=el.value;s.examResult=null;saveExamDraft();document.getElementById('awExamResults')?.remove();}
});
ROOT.addEventListener('change',e=>{const el=e.target;
 if(el.hasAttribute('data-aw-mark-example')){s.markIndex=Number(el.value);s.markMap=cityData[s.markIndex].map;s.markPoint=null;s.markFeedback=null;s.markSolution=false;renderHere();}
 if(el.hasAttribute('data-aw-mark-map')){s.markMap=el.value;s.markPoint=null;s.markFeedback=null;renderHere();}
 if(el.hasAttribute('data-aw-atlas-map')){s.atlasMap=el.value;renderHere();}
 if(el.hasAttribute('data-aw-register-place')){s.registerChoice=el.value;s.registerResult=null;}
 if(el.hasAttribute('data-aw-register-map')){s.registerMapChoice=el.value;s.registerResult=null;renderHere();}
 if(el.dataset.awExam){if(s.examSubmitted)return;s.examAnswers[el.dataset.awExam]=el.value;s.examResult=null;saveExamDraft();document.getElementById('awExamResults')?.remove();}
});
ROOT.addEventListener('toggle',e=>{if(e.target.hasAttribute?.('data-aw-gap-reference')&&e.target.open)s.gapSeenSolution=true;if(e.target.hasAttribute?.('data-aw-gap-help')&&e.target.open)s.gapHelpUsed=true;if(e.target.hasAttribute?.('data-aw-view-help')&&e.target.open)s.viewHelpUsed=true;if(e.target.hasAttribute?.('data-aw-quarter-help')&&e.target.open)s.quarterHelpUsed=true;},true);
function compactMainNavigation(){
 const nav=document.getElementById('tabs');if(!nav||document.getElementById('awMoreMain'))return;
 const keep=new Set(['start','guided','atlaswerkstatt','learn','progress']),more=document.createElement('details');more.id='awMoreMain';more.className='aw-more-main';
 const summary=document.createElement('summary');summary.textContent='Weitere App-Bereiche';more.appendChild(summary);const content=document.createElement('div');content.className='aw-more-content';
 nav.querySelectorAll('button[data-tab]').forEach(b=>{if(!keep.has(b.dataset.tab))content.appendChild(b);});more.appendChild(content);nav.insertAdjacentElement('afterend',more);
 more.addEventListener('click',e=>{const b=e.target.closest('button[data-tab]');if(!b)return;more.open=false;switchTab(b.dataset.tab);});
}
function syncMore(){document.querySelectorAll('#awMoreMain button[data-tab]').forEach(b=>{const active=b.dataset.tab===state.tab;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});}

const oldRender=render;
render=function(){if(state.tab!=='atlaswerkstatt'){stop();oldRender();syncMore();return;}updateStars();document.documentElement.dataset.theme=progress.theme;document.documentElement.dataset.contrast=progress.contrast;document.documentElement.style.setProperty('--fontScale',String(progress.font));document.querySelectorAll('#tabs button').forEach(b=>{const active=b.dataset.tab==='atlaswerkstatt';b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});ROOT.innerHTML=show();syncMore();};
const nav=document.getElementById('tabs'),tab=document.createElement('button');tab.type='button';tab.dataset.tab='atlaswerkstatt';tab.textContent='🌐 Gradnetz & Atlas';nav.insertBefore(tab,nav.querySelector('[data-tab="learn"]'));compactMainNavigation();
const entry=()=>`<section class="card aw-entry"><div class="eyebrow">Neu · passend zu deinen Unterrichtsskizzen</div><h2>🌐 Gradnetz & Atlas</h2><p>Erde drehen · Erdviertel erkennen · Blick auf den Pol · 20 Orte selbst markieren · Register nutzen.</p><div class="aw-controls">${button('NEU: Interaktive Klassenarbeit · 18 Aufgaben','openClasswork','class="aw-primary"')}${pdfLinks(false)}</div><button type="button" class="btn" data-aw="open">Gradnetz- und Atlaswerkstatt öffnen →</button></section>`;
if(typeof renderTests==='function'){const oldTests=renderTests;renderTests=function(){return `<section class="card"><h2>Aktueller Test nach deinen Unterrichtsskizzen</h2><p>9 Seiten mit Draufsicht, Erdkugeln zum Einzeichnen, Viertelkugeln und deinem Lückentext.</p>${button('Interaktive Klassenarbeit · alle 18 PDF-Aufgaben','openClasswork','class="aw-primary"')}${pdfLinks(false)}</section><details><summary>Weitere Übungstests aus früheren Bereichen</summary>`+oldTests()+'</details>';};}
const oldStart=renderStart;renderStart=function(){return entry()+oldStart();};
const oldLesson=renderLesson;renderLesson=function(){const result=oldLesson();return ['gradnetz','atlanten'].includes(state.topic)?entry()+result:result;};
window.AtlasWerkstatt=Object.freeze({quarter,number,checkMissing,project,cityData,maps,fieldFor,coord,normalize,checkGaps,coordinateFeedback,pointFromMap,gradeExam,examRegisterRows,cleanSketch,originalScene,cwTasks,gradeClasswork,cleanClasswork});
render();
})();
